--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: app_alcance(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.app_alcance() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
           when p.rol_id = 'AREA' then p.empresa_id
           else coalesce(p.alcance_empresa,'TODAS')
         end
  from perfil p
  where p.id = auth.uid() and p.activo;
$$;


ALTER FUNCTION public.app_alcance() OWNER TO postgres;

--
-- Name: app_alcance_ef(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.app_alcance_ef() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case
    when coalesce((select p.seguimiento_global from perfil p
                    where p.id = auth.uid() and p.activo), false)
      then (select p.alcance_empresa from perfil p
             where p.id = auth.uid() and p.activo)
    else public.app_alcance()
  end;
$$;


ALTER FUNCTION public.app_alcance_ef() OWNER TO postgres;

