--
-- Name: dias_lab(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.dias_lab(d1 date, d2 date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  select case when d2 < d1 then -1 else 1 end *
         (select count(*)::int
            from generate_series(least(d1,d2), greatest(d1,d2), interval '1 day') g
           where extract(isodow from g) < 6);
$$;


ALTER FUNCTION public.dias_lab(d1 date, d2 date) OWNER TO postgres;

--
-- Name: fn_anular_tarea(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_anular_tarea(p_id text, p_motivo text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller  uuid := auth.uid();
  v_admin   boolean;
  v_usuario text;
  v_estado  text;
  v_tema    text;
  v_check   boolean;
  v_sello   text;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Sesión no válida.';
  END IF;

  SELECT super_usuario, usuario INTO v_admin, v_usuario
  FROM perfil WHERE id = v_caller;

  IF COALESCE(v_admin, false) <> true THEN
    RAISE EXCEPTION 'Solo el superusuario puede anular tareas.';
  END IF;

  IF p_motivo IS NULL OR length(btrim(p_motivo)) < 5 THEN
    RAISE EXCEPTION 'El motivo es obligatorio (mínimo 5 caracteres).';
  END IF;

  SELECT estado_avance_cod, nombre_tema, check_analista
    INTO v_estado, v_tema, v_check
  FROM compromiso WHERE id_compromiso = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'La tarea % no existe.', p_id;
  END IF;

  IF v_estado = 'INACTIVO' THEN
    RAISE EXCEPTION 'La tarea % ya está anulada.', p_id;
  END IF;

  v_sello := '🚫 ANULADA por ' || COALESCE(v_usuario, '?')
          || ' el ' || to_char(now() AT TIME ZONE 'America/Lima', 'DD/MM/YYYY HH24:MI')
          || ' — Motivo: ' || btrim(p_motivo);

  UPDATE compromiso SET
    estado_avance_cod = 'INACTIVO',
    check_analista    = false,   -- la saca del ranking
    check_blesola     = false,
    check_fermet      = false,
    comentario_final  = CASE
                          WHEN COALESCE(btrim(comentario_final), '') = '' THEN v_sello
                          ELSE comentario_final || E'\n' || v_sello
                        END,
    fecha_actualizacion_final = now()
  WHERE id_compromiso = p_id;

  RETURN json_build_object(
    'ok', true,
    'id', p_id,
    'tema', v_tema,
    'estado_anterior', v_estado,
    'estaba_aprobada', COALESCE(v_check, false)
  );
END;
$$;


ALTER FUNCTION public.fn_anular_tarea(p_id text, p_motivo text) OWNER TO postgres;

