--
-- Name: fn_crear_tarea(uuid[], text, date, text[], text, text, text, text, boolean, boolean, date, uuid, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crear_tarea(p_responsables uuid[], p_detalle_compromiso text, p_fecha_entrega date, p_areas text[] DEFAULT NULL::text[], p_nombre_tema text DEFAULT NULL::text, p_proyecto_asociado text DEFAULT NULL::text, p_asignacion_compromiso text DEFAULT NULL::text, p_prioridad text DEFAULT NULL::text, p_reunion_presencial boolean DEFAULT false, p_confidencial boolean DEFAULT false, p_fecha_asignada date DEFAULT public.fn_hoy(), p_asignado_por uuid DEFAULT NULL::uuid, p_grupal boolean DEFAULT false) RETURNS TABLE(id_compromiso text, responsable text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_lote     uuid := gen_random_uuid();
  v_uid      uuid := coalesce(p_asignado_por, auth.uid());
  v_creado   uuid := auth.uid();
  v_resp     uuid;
  v_area     text;
  v_emp      text;
  v_id       text;
  v_vistos   uuid[] := '{}';
  v_i        int := 0;
  v_nareas   int := coalesce(array_length(p_areas, 1), 0);
  v_nresp    int;
  v_nres_col int;
begin
  if not app_puede_asignar() then
    raise exception 'No autorizado: tu usuario no tiene PUEDE_ASIGNAR';
  end if;

  -- MIGRACION 31 · tarea programada. La fecha futura es un permiso, no
  -- una opcion del formulario.
  if p_fecha_asignada > fn_hoy() and not app_ve_programadas() then
    raise exception 'No autorizado: tu usuario no puede programar tareas a futuro';
  end if;

  if p_responsables is null or array_length(p_responsables,1) is null then
    raise exception 'Debes indicar al menos un responsable';
  end if;
  if array_length(p_responsables,1) > 20 then
    raise exception 'Máximo 20 responsables por tarea';
  end if;
  if coalesce(trim(p_detalle_compromiso),'') = '' then
    raise exception 'El detalle del compromiso es obligatorio';
  end if;
  if p_fecha_entrega < p_fecha_asignada then
    raise exception 'La fecha de entrega no puede ser anterior a la de asignación';
  end if;
  if v_nareas > 1 and v_nareas <> array_length(p_responsables, 1) then
    raise exception 'p_areas debe tener 1 elemento, o tantos como responsables';
  end if;

  select count(distinct x) into v_nresp from unnest(p_responsables) x;

  if p_grupal and v_nresp < 2 then
    raise exception 'Una tarea grupal necesita al menos dos responsables distintos';
  end if;

  -- Acá está la diferencia entre Individual y Grupal.
  -- Individual → cada fila vale por sí sola y se lleva el puntaje completo.
  -- Grupal     → las filas son una sola tarea y el puntaje se reparte.
  v_nres_col := case when p_grupal then v_nresp else 1 end;

  foreach v_resp in array p_responsables loop
    v_i := v_i + 1;
    continue when v_resp = any(v_vistos);
    v_vistos := v_vistos || v_resp;

    select p.empresa_id into v_emp
    from perfil p where p.id = v_resp and p.activo;
    if v_emp is null then
      raise exception 'Responsable % no existe o está inactivo', v_resp;
    end if;

    if not app_puede_asignar_a(v_emp) then
      raise exception 'No autorizado: no puedes asignar tareas de la empresa %', v_emp;
    end if;

    v_area := case
                when v_nareas = 1 then p_areas[1]
                when v_nareas > 1 then p_areas[v_i]
                else null
              end;

    if v_area is null then
      select pa.area_prefijo into v_area
      from perfil_area pa where pa.perfil_id = v_resp
      order by pa.area_prefijo limit 1;
      if v_area is null then
        raise exception 'El responsable % no tiene área en perfil_area', v_resp;
      end if;
    else
      if not exists (select 1 from perfil_area pa
                      where pa.perfil_id = v_resp and pa.area_prefijo = v_area) then
        raise exception 'El área % no corresponde al responsable %', v_area, v_resp;
      end if;
    end if;

    v_id := fn_siguiente_id(v_area, v_emp);

    insert into compromiso(
      id_compromiso, id_lote, id_acta, nombre_tema, proyecto_asociado,
      asignacion_compromiso, prioridad, area_prefijo, empresa_id,
      detalle_compromiso, responsable_id, asignado_por_id, creado_por_id,
      n_responsables,
      fecha_asignada, fecha_entrega, reunion_presencial, confidencial,
      estado_avance_cod, estado_final_cod)
    values (
      v_id, v_lote, 'PLATAFORMA', p_nombre_tema, p_proyecto_asociado,
      p_asignacion_compromiso, p_prioridad, v_area, v_emp,
      p_detalle_compromiso, v_resp, v_uid, v_creado,
      v_nres_col,
      p_fecha_asignada, p_fecha_entrega, p_reunion_presencial, p_confidencial,
      'EN_PROCESO', 'EN_PROCESO');

    if p_confidencial then
      insert into bitacora(usuario_id, id_compromiso, campo, valor)
      values (v_creado, v_id, 'CONFIDENCIAL', 'Tarea creada como confidencial');
    end if;

    if p_grupal then
      insert into bitacora(usuario_id, id_compromiso, campo, valor)
      values (v_creado, v_id, 'GRUPAL',
              'Tarea grupal · ' || v_nresp || ' responsables · el puntaje se reparte');
    end if;

    id_compromiso := v_id;
    select nombre_completo into responsable from perfil where id = v_resp;
    return next;
  end loop;
end $$;


ALTER FUNCTION public.fn_crear_tarea(p_responsables uuid[], p_detalle_compromiso text, p_fecha_entrega date, p_areas text[], p_nombre_tema text, p_proyecto_asociado text, p_asignacion_compromiso text, p_prioridad text, p_reunion_presencial boolean, p_confidencial boolean, p_fecha_asignada date, p_asignado_por uuid, p_grupal boolean) OWNER TO postgres;

--
-- Name: fn_crear_tarea_masiva(uuid[], text, date, text[], text, text, text, text, boolean, boolean, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_crear_tarea_masiva(p_responsables uuid[], p_detalle_compromiso text, p_fecha_entrega date, p_areas text[] DEFAULT NULL::text[], p_nombre_tema text DEFAULT NULL::text, p_proyecto_asociado text DEFAULT NULL::text, p_asignacion_compromiso text DEFAULT NULL::text, p_prioridad text DEFAULT NULL::text, p_reunion_presencial boolean DEFAULT false, p_confidencial boolean DEFAULT false, p_fecha_asignada date DEFAULT public.fn_hoy(), p_asignado_por uuid DEFAULT NULL::uuid) RETURNS TABLE(id_compromiso text, responsable text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r      record;
  v_ids  text[] := '{}';
begin
  for r in
    select t.id_compromiso, t.responsable
      from public.fn_crear_tarea(
             p_responsables,
             p_detalle_compromiso,
             p_fecha_entrega,
             p_areas,
             p_nombre_tema,
             p_proyecto_asociado,
             p_asignacion_compromiso,
             p_prioridad,
             p_reunion_presencial,
             p_confidencial,
             p_fecha_asignada,
             p_asignado_por,
             false
           ) t
  loop
    v_ids := v_ids || r.id_compromiso;
    id_compromiso := r.id_compromiso;
    responsable   := r.responsable;
    return next;
  end loop;

  if array_length(v_ids, 1) is not null then
    update public.compromiso as c
       set es_masiva = true
     where c.id_compromiso = any(v_ids);
  end if;

  return;
end;
$$;


ALTER FUNCTION public.fn_crear_tarea_masiva(p_responsables uuid[], p_detalle_compromiso text, p_fecha_entrega date, p_areas text[], p_nombre_tema text, p_proyecto_asociado text, p_asignacion_compromiso text, p_prioridad text, p_reunion_presencial boolean, p_confidencial boolean, p_fecha_asignada date, p_asignado_por uuid) OWNER TO postgres;

