--
-- Name: fn_notif_barrer(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notif_barrer() RETURNS TABLE(tipo text, encolados integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  n_asig integer := 0;
  n_pv   integer := 0;
  n_ven  integer := 0;
begin
  -- === 1 · Programadas que se publican hoy ============================
  with pub as (
    insert into notificacion_cola
      (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
    select c.responsable_id, c.id_compromiso,
           coalesce(c.id_lote::text, c.id_compromiso),
           'ASIGNADA', 'RESPONSABLE', c.empresa_id
      from compromiso c
      join perfil p on p.id = c.responsable_id
     where c.fecha_asignada = fn_hoy()
       and c.estado_avance_cod not in ('INACTIVO','NO_APLICA')
       and p.activo
       and p.email_notificacion is not null
    on conflict on constraint notificacion_cola_unica do nothing
    returning 1)
  select count(*) into n_asig from pub;

  -- === 2 · POR_VENCER · al responsable y a gestion =====================
  with pv as (
    insert into notificacion_cola
      (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
    select d.id, c.id_compromiso,
           coalesce(c.id_lote::text, c.id_compromiso),
           'POR_VENCER', d.motivo, c.empresa_id
      from compromiso c
      cross join lateral (
            -- el responsable
            select p.id, 'RESPONSABLE'::text as motivo
              from perfil p
             where p.id = c.responsable_id
               and p.activo and p.email_notificacion is not null
            union all
            -- gestion, acotada por alcance y por confidencialidad
            select p.id, 'GESTION'::text
              from perfil p
             where p.activo
               and p.rol_id in ('GERENCIA','SUBGERENCIA','ANALISTA')
               and p.email_notificacion is not null
               and (p.alcance_empresa = 'TODAS' or p.alcance_empresa = c.empresa_id)
               and (not c.confidencial or coalesce(p.ve_confidencial, false))
               and p.id <> c.responsable_id
      ) d
     where c.estado_avance_cod = 'EN_PROCESO'
       and c.fecha_asignada <= fn_hoy()          -- no programada
       and c.fecha_entrega is not null
       and fn_hoy() <= c.fecha_entrega           -- todavia no vencida
       and dias_lab(fn_hoy() + 1, c.fecha_entrega) <= 3
    on conflict on constraint notificacion_cola_unica do nothing
    returning 1)
  select count(*) into n_pv from pv;

  -- === 3 · VENCIDO · solo al responsable ==============================
  -- Se implementa como se pidio. Ver la observacion al final: gestion se
  -- entera de POR_VENCER pero no de que efectivamente vencio.
  with vn as (
    insert into notificacion_cola
      (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
    select c.responsable_id, c.id_compromiso,
           coalesce(c.id_lote::text, c.id_compromiso),
           'VENCIDO', 'RESPONSABLE', c.empresa_id
      from compromiso c
      join perfil p on p.id = c.responsable_id
     where c.estado_avance_cod = 'EN_PROCESO'
       and c.fecha_asignada <= fn_hoy()
       and c.fecha_entrega is not null
       and fn_hoy() > c.fecha_entrega
       and p.activo
       and p.email_notificacion is not null
    on conflict on constraint notificacion_cola_unica do nothing
    returning 1)
  select count(*) into n_ven from vn;

  return query
    select 'ASIGNADA'::text, n_asig
    union all select 'POR_VENCER', n_pv
    union all select 'VENCIDO',    n_ven;
end $$;


ALTER FUNCTION public.fn_notif_barrer() OWNER TO postgres;

--
-- Name: FUNCTION fn_notif_barrer(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_notif_barrer() IS 'Encola las alertas derivadas de fecha (POR_VENCER, VENCIDO) y publica las programadas que llegan a su fecha. Replica las expresiones del CASE de v_compromiso: si ese CASE cambia, esta funcion tambien.';


--
-- Name: fn_notif_encolar(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_notif_encolar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_clave  text;
  v_nuevo  text := new.estado_avance_cod;
  v_viejo  text := coalesce(old.estado_avance_cod, '');
begin
  -- Las anuladas no avisan nada, nunca.
  if v_nuevo in ('INACTIVO','NO_APLICA') then
    return null;
  end if;

  v_clave := coalesce(new.id_lote::text, new.id_compromiso);

  -- === ASIGNADA ======================================================
  -- Solo si la tarea ya esta publicada. Una programada con fecha futura
  -- no avisa: el aviso llegaria de una tarea que la plataforma le
  -- esconde al responsable (migracion 31). La publica la tanda 4 el dia
  -- que le toca.
  if (tg_op = 'INSERT')
     or (tg_op = 'UPDATE' and new.responsable_id is distinct from old.responsable_id)
  then
    if new.fecha_asignada <= fn_hoy() then
      insert into notificacion_cola
        (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
      values
        (new.responsable_id, new.id_compromiso, v_clave, 'ASIGNADA',
         'RESPONSABLE', new.empresa_id)
      on conflict on constraint notificacion_cola_unica do nothing;
    end if;
  end if;

  -- === REPROCESO · al responsable ====================================
  if tg_op = 'UPDATE' and v_nuevo = 'REPROCESO' and v_viejo <> 'REPROCESO' then
    insert into notificacion_cola
      (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
    values
      (new.responsable_id, new.id_compromiso, v_clave, 'REPROCESO',
       'RESPONSABLE', new.empresa_id)
    on conflict on constraint notificacion_cola_unica do nothing;
  end if;

  -- === BLOQUEADO y REALIZADO · a gestion ==============================
  if tg_op = 'UPDATE'
     and v_nuevo in ('BLOQUEADO','REALIZADO')
     and v_viejo is distinct from v_nuevo
  then
    insert into notificacion_cola
      (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
    select p.id, new.id_compromiso, v_clave, v_nuevo, 'GESTION', new.empresa_id
      from perfil p
     where p.activo
       and p.rol_id in ('GERENCIA','SUBGERENCIA','ANALISTA')
       and p.email_notificacion is not null
       and (p.alcance_empresa = 'TODAS' or p.alcance_empresa = new.empresa_id)
       -- Confidenciales: el correo sale del RLS y viaja a un buzon.
       -- Quien no las ve en la plataforma tampoco las ve por correo.
       -- OJO: no se evalua confidencial_empresa. Ver nota al final.
       and (not new.confidencial or coalesce(p.ve_confidencial, false))
       -- El responsable no se avisa a si mismo de su propia accion.
       and p.id <> new.responsable_id
    on conflict on constraint notificacion_cola_unica do nothing;
  end if;

  -- === REALIZADO · al que asigno ======================================
  -- Va como fila propia, no como copia del correo. En Brevo cada
  -- destinatario de To/CC/BCC cuenta como un envio aparte contra la
  -- cuota; y ademas el asignador suele ser Vilma o Lilian, que ya reciben
  -- su resumen de gestion. Con motivo='ASIGNADOR' la Edge Function lo
  -- agrupa como seccion "Tareas que asignaste" dentro de ESE mismo
  -- resumen. Misma informacion, cero correos extra.
  if tg_op = 'UPDATE'
     and v_nuevo = 'REALIZADO' and v_viejo <> 'REALIZADO'
     and new.asignado_por_id is not null
     and new.asignado_por_id <> new.responsable_id
  then
    insert into notificacion_cola
      (destinatario_id, id_compromiso, clave_lote, tipo, motivo, empresa_id)
    select p.id, new.id_compromiso, v_clave, 'REALIZADO', 'ASIGNADOR', new.empresa_id
      from perfil p
     where p.id = new.asignado_por_id
       and p.activo
       and p.email_notificacion is not null
       and (not new.confidencial or coalesce(p.ve_confidencial, false))
    on conflict on constraint notificacion_cola_unica do nothing;
  end if;

  return null;
end $$;


