-- Name: FUNCTION fn_notif_encolar(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.fn_notif_encolar() IS 'Encola avisos de eventos con estado guardado. No envia correo: solo escribe en notificacion_cola. POR_VENCER y VENCIDO no pasan por aqui.';


--
-- Name: fn_ping(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ping() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null then
    return;
  end if;

  update public.perfil
     set ultimo_acceso = now()
   where id = auth.uid();
end;
$$;


ALTER FUNCTION public.fn_ping() OWNER TO postgres;

--
-- Name: fn_por_ajustar(text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_por_ajustar(p_id text, p_comentario text, p_nueva_fecha date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_emp   text;
  v_lote  uuid;
  v_nresp smallint;
  v_asig  uuid;
begin
  select c.empresa_id, c.id_lote, c.n_responsables, c.asignado_por_id
    into v_emp, v_lote, v_nresp, v_asig
    from compromiso c where c.id_compromiso = p_id;

  if v_emp is null then
    raise exception 'Compromiso % no existe', p_id;
  end if;
  if not app_puede_cerrar_en(v_emp, v_asig) then
    raise exception 'No autorizado para devolver tareas en esta empresa (%)', v_emp;
  end if;
  if p_nueva_fecha is null then
    raise exception 'Debes indicar la nueva fecha de entrega';
  end if;

  perform set_config('app.fn_bypass', '1', true);
  perform set_config('app.lote_sync', '1', true);

  update compromiso set
    estado_avance_cod  = 'POR_AJUSTAR',
    estado_final_cod   = 'POR_AJUSTAR',
    comentario_final   = p_comentario,
    fecha_entrega_real = null,
    fecha_entrega      = p_nueva_fecha,
    check_analista = false, check_analista_por = null, check_analista_en = null,
    check_blesola  = false, check_blesola_por  = null, check_blesola_en  = null,
    check_fermet   = false, check_fermet_por   = null, check_fermet_en   = null,
    fecha_actualizacion_final = now()
  where id_compromiso = p_id
     or (v_lote is not null and v_nresp > 1 and id_lote = v_lote
         and estado_avance_cod <> 'INACTIVO');

  perform set_config('app.fn_bypass', '', true);
  perform set_config('app.lote_sync', '', true);
end $$;


ALTER FUNCTION public.fn_por_ajustar(p_id text, p_comentario text, p_nueva_fecha date) OWNER TO postgres;

--
-- Name: fn_puntuar(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_puntuar(p_id text, q1 integer, q2 integer, q3 integer) RETURNS smallint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_pts     smallint;
  v_q       int;
  v_emp     text;
  v_creador uuid;
  v_actual  smallint;
  v_lote    uuid;
  v_nresp   int;
begin
  select c.empresa_id, c.creado_por_id, c.puntaje_base, c.id_lote,
         coalesce(c.n_responsables, 1)
    into v_emp, v_creador, v_actual, v_lote, v_nresp
    from compromiso c
   where c.id_compromiso = p_id;

  if v_emp is null then
    raise exception 'La tarea % no existe', p_id;
  end if;

  -- ── v84 · convertir una tarea SIN PUNTAJE en una CON PUNTAJE es privativo
  --    del Administrador. Cambia el denominador del ranking retroactivamente.
  if v_actual = 0 and not app_es_admin() then
    raise exception 'Esta tarea se creo sin puntaje. Solo el Administrador puede asignarle un puntaje';
  end if;

  -- ── Quien puede puntuar (migracion 22) ───────────────────────────────────
  if not (
       app_es_admin()
    or (app_edita_puntaje()
        and (app_puntaje_empresa() = 'TODAS' or app_puntaje_empresa() = v_emp))
    or (v_creador = auth.uid() and v_actual is null and app_puede_asignar_a(v_emp))
  ) then
    if v_actual is not null and v_creador = auth.uid() then
      raise exception 'Esta tarea ya tiene puntaje. Para modificarlo necesitas el permiso de validar y ajustar puntajes';
    end if;
    raise exception 'No autorizado para puntuar tareas de la empresa %', v_emp;
  end if;

  foreach v_q in array array[q1, q2, q3] loop
    if v_q is null or v_q < 10 or v_q > 50 or v_q % 10 <> 0 then
      raise exception 'Cada respuesta debe ser 10, 20, 30, 40 o 50';
    end if;
  end loop;

  v_pts := greatest(10, least(50, round((q1 + q2 + q3)::numeric / 3)))::smallint;

  perform set_config('app.fn_bypass', '1', true);

  update compromiso c set
    puntaje_base         = v_pts,
    rubrica              = 'C' || q1 || '|D' || q2 || '|A' || q3,
    puntaje_validado     = false,
    puntaje_validado_por = null,
    puntaje_validado_en  = null
  where c.estado_avance_cod <> 'INACTIVO'
    and ( c.id_compromiso = p_id
       or (v_nresp > 1 and v_lote is not null and c.id_lote = v_lote) );

  perform set_config('app.fn_bypass', '', true);

  return v_pts;
end $$;


ALTER FUNCTION public.fn_puntuar(p_id text, q1 integer, q2 integer, q3 integer) OWNER TO postgres;

--
-- Name: norm_txt(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.norm_txt(s text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  select regexp_replace(
           trim(translate(lower(coalesce(s,'')),
                          'áàäâéèëêíìïîóòöôúùüûñç',
                          'aaaaeeeeiiiioooouuuunc')),
           '\s+', ' ', 'g');
$$;


ALTER FUNCTION public.norm_txt(s text) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: compromiso; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.compromiso (
    id_compromiso text NOT NULL,
    id_lote uuid,
    id_acta text,
    fecha_reunion date,
    id_tema text,
    nombre_tema text,
    detalle_tema text,
    proyecto_asociado text,
    asignacion_compromiso text,
    prioridad text,
    area_prefijo text NOT NULL,
    empresa_id text NOT NULL,
    detalle_compromiso text NOT NULL,
    responsable_id uuid NOT NULL,
    asignado_por_id uuid,
    fecha_asignada date NOT NULL,
    fecha_entrega date NOT NULL,
    reunion_presencial boolean DEFAULT false NOT NULL,
    confidencial boolean DEFAULT false NOT NULL,
    estado_avance_cod text,
    comentario_compromiso text,
    ruta_archivo text,
    fecha_ult_actualizacion timestamp with time zone,
    estado_final_cod text,
    comentario_final text,
    fecha_entrega_real date,
    fecha_actualizacion_final timestamp with time zone,
    check_analista boolean DEFAULT false NOT NULL,
    check_analista_por uuid,
    check_analista_en timestamp with time zone,
    check_blesola boolean DEFAULT false NOT NULL,
    check_blesola_por uuid,
    check_blesola_en timestamp with time zone,
    check_fermet boolean DEFAULT false NOT NULL,
    check_fermet_por uuid,
    check_fermet_en timestamp with time zone,
    rubrica text,
    puntaje_base smallint,
    reprocesos smallint DEFAULT 0 NOT NULL,
    fuera_fecha boolean GENERATED ALWAYS AS (((fecha_entrega IS NOT NULL) AND (fecha_entrega_real IS NOT NULL) AND (fecha_entrega_real > fecha_entrega))) STORED,
    puntaje_final smallint GENERATED ALWAYS AS (
CASE
    WHEN (puntaje_base IS NULL) THEN NULL::integer
    ELSE GREATEST(0, ((puntaje_base - (5 * COALESCE((reprocesos)::integer, 0))) -
    CASE
        WHEN ((fecha_entrega IS NOT NULL) AND (fecha_entrega_real IS NOT NULL) AND (fecha_entrega_real > fecha_entrega)) THEN 5
        ELSE 0
    END))
END) STORED,
    creado_en timestamp with time zone DEFAULT now() NOT NULL,
    actualizado_en timestamp with time zone DEFAULT now() NOT NULL,
    puntaje_validado boolean DEFAULT false NOT NULL,
    puntaje_validado_por uuid,
    puntaje_validado_en timestamp with time zone,
    creado_por_id uuid,
    n_responsables smallint DEFAULT 1 NOT NULL,
    puntaje_persona smallint GENERATED ALWAYS AS (
CASE
    WHEN (puntaje_base IS NULL) THEN NULL::smallint
    ELSE (ceil(((GREATEST(0, ((puntaje_base - (5 * COALESCE((reprocesos)::integer, 0))) -
    CASE
        WHEN ((fecha_entrega IS NOT NULL) AND (fecha_entrega_real IS NOT NULL) AND (fecha_entrega_real > fecha_entrega)) THEN 5
        ELSE 0
    END)))::numeric / (GREATEST((n_responsables)::integer, 1))::numeric)))::smallint
END) STORED,
    es_masiva boolean DEFAULT false NOT NULL,
    CONSTRAINT compromiso_n_responsables_chk CHECK ((n_responsables >= 1)),
    CONSTRAINT compromiso_puntaje_base_check CHECK (((puntaje_base IS NULL) OR ((puntaje_base >= 0) AND (puntaje_base <= 50))))
);


