    CONSTRAINT perfil_asignar_empresa_chk CHECK ((asignar_empresa = ANY (ARRAY['TODAS'::text, 'BLE'::text, 'FER'::text]))),
    CONSTRAINT perfil_cerrar_empresa_chk CHECK ((cerrar_empresa = ANY (ARRAY['BLE'::text, 'FER'::text, 'TODAS'::text]))),
    CONSTRAINT perfil_columna_vb_chk CHECK (((columna_vb IS NULL) OR (columna_vb = ANY (ARRAY['A'::text, 'B'::text, 'F'::text])))),
    CONSTRAINT perfil_confidencial_empresa_chk CHECK ((confidencial_empresa = ANY (ARRAY['BLE'::text, 'FER'::text, 'TODAS'::text]))),
    CONSTRAINT perfil_puntaje_empresa_chk CHECK ((puntaje_empresa = ANY (ARRAY['TODAS'::text, 'BLE'::text, 'FER'::text])))
);


