--
-- Name: v_ranking_persona; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_ranking_persona AS
 WITH filas AS (
         SELECT c.responsable_id,
            c.area_prefijo,
            c.empresa_id,
            c.check_analista,
            c.estado_avance_cod,
            c.puntaje_validado,
            c.reprocesos,
            c.fuera_fecha,
            c.puntaje_base,
            round(((c.puntaje_base)::numeric / (GREATEST(COALESCE((c.n_responsables)::integer, 1), 1))::numeric), 1) AS pb_persona,
            round(((c.puntaje_final)::numeric / (GREATEST(COALESCE((c.n_responsables)::integer, 1), 1))::numeric), 1) AS pf_persona
           FROM public.compromiso c
          WHERE ((COALESCE(c.estado_avance_cod, ''::text) <> 'INACTIVO'::text) AND (COALESCE((c.puntaje_base)::integer, '-1'::integer) <> 0))
        )
 SELECT f.responsable_id,
    p.nombre_completo AS persona,
    f.area_prefijo,
    f.empresa_id,
    count(*) AS tareas,
    count(*) FILTER (WHERE (f.check_analista AND (COALESCE(f.estado_avance_cod, ''::text) <> 'REPROCESO'::text))) AS cerradas,
    round(COALESCE(sum(f.pb_persona) FILTER (WHERE (f.check_analista AND (COALESCE(f.estado_avance_cod, ''::text) <> 'REPROCESO'::text) AND f.puntaje_validado)), (0)::numeric), 1) AS puntaje_asignado,
    round(COALESCE(sum(f.pf_persona) FILTER (WHERE (f.check_analista AND (COALESCE(f.estado_avance_cod, ''::text) <> 'REPROCESO'::text) AND f.puntaje_validado)), (0)::numeric), 1) AS puntaje_final_sum,
    COALESCE(sum(f.reprocesos) FILTER (WHERE (f.check_analista AND (COALESCE(f.estado_avance_cod, ''::text) <> 'REPROCESO'::text) AND f.puntaje_validado)), (0)::bigint) AS reprocesos,
    count(*) FILTER (WHERE (f.fuera_fecha AND f.check_analista AND (COALESCE(f.estado_avance_cod, ''::text) <> 'REPROCESO'::text) AND f.puntaje_validado)) AS fuera_fecha,
    count(*) FILTER (WHERE (f.puntaje_base IS NULL)) AS sin_puntaje,
    count(*) FILTER (WHERE ((f.puntaje_base IS NOT NULL) AND (NOT f.puntaje_validado))) AS sin_validar
   FROM (filas f
     JOIN public.perfil p ON ((p.id = f.responsable_id)))
  GROUP BY f.responsable_id, p.nombre_completo, f.area_prefijo, f.empresa_id;


ALTER VIEW public.v_ranking_persona OWNER TO postgres;

