--
-- Name: fn_registrar_vb(text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_registrar_vb(p_id text, p_valor boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_emp   text;
  v_lote  uuid;
  v_nresp smallint;
  v_est   text;
  v_col   text;
  v_asig  uuid;
begin
  select c.empresa_id, c.id_lote, c.n_responsables, c.estado_avance_cod, c.asignado_por_id
    into v_emp, v_lote, v_nresp, v_est, v_asig
    from compromiso c
   where c.id_compromiso = p_id;

  if v_emp is null then
    raise exception 'Compromiso % no existe', p_id;
  end if;

  select p.columna_vb into v_col
    from perfil p where p.id = v_uid and p.activo;

  -- migracion 33 · el cierre se acota tambien por quien asigno la tarea
  if app_puede_cerrar_en(v_emp, v_asig) then
    if p_valor and v_est is distinct from 'REALIZADO' and not app_es_admin() then
      raise exception 'La tarea debe estar en REALIZADO para aprobarse (estado actual: %)', coalesce(v_est,'sin estado');
    end if;

    perform set_config('app.fn_bypass', '1', true);
    perform set_config('app.lote_sync', '1', true);

    update compromiso set
      check_analista     = p_valor,
      check_analista_por = case when p_valor then v_uid else null end,
      check_analista_en  = case when p_valor then now() else null end,
      estado_final_cod   = case when p_valor then 'APROBADO' else estado_final_cod end,
      fecha_actualizacion_final = now()
    where id_compromiso = p_id
       or (v_lote is not null and v_nresp > 1 and id_lote = v_lote
           and estado_avance_cod <> 'INACTIVO');

    perform set_config('app.fn_bypass', '', true);
    perform set_config('app.lote_sync', '', true);
    return;
  end if;

  if v_col = 'B' and v_emp = 'BLE' then
    perform set_config('app.fn_bypass', '1', true);
    perform set_config('app.lote_sync', '1', true);
    update compromiso set check_blesola = p_valor,
      check_blesola_por = case when p_valor then v_uid else null end,
      check_blesola_en  = case when p_valor then now() else null end
    where id_compromiso = p_id
       or (v_lote is not null and v_nresp > 1 and id_lote = v_lote
           and estado_avance_cod <> 'INACTIVO');
    perform set_config('app.fn_bypass', '', true);
    perform set_config('app.lote_sync', '', true);
    return;
  end if;

  if v_col = 'F' and v_emp = 'FER' then
    perform set_config('app.fn_bypass', '1', true);
    perform set_config('app.lote_sync', '1', true);
    update compromiso set check_fermet = p_valor,
      check_fermet_por = case when p_valor then v_uid else null end,
      check_fermet_en  = case when p_valor then now() else null end
    where id_compromiso = p_id
       or (v_lote is not null and v_nresp > 1 and id_lote = v_lote
           and estado_avance_cod <> 'INACTIVO');
    perform set_config('app.fn_bypass', '', true);
    perform set_config('app.lote_sync', '', true);
    return;
  end if;

  raise exception 'No autorizado: no tienes visto bueno sobre esta empresa (%)', v_emp;
end $$;


ALTER FUNCTION public.fn_registrar_vb(p_id text, p_valor boolean) OWNER TO postgres;

--
-- Name: fn_reporte_actividad(date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reporte_actividad(p_desde date DEFAULT NULL::date, p_hasta date DEFAULT NULL::date) RETURNS TABLE(usuario text, nombre_completo text, rol_id text, empresa_id text, areas text, activo boolean, password_cambiado boolean, ultimo_login timestamp with time zone, ultimo_ping timestamp with time zone, ultima_accion timestamp with time zone, ultima_accion_detalle text, dias_sin_actividad integer, semaforo text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare
  v_super  boolean;
  v_corte  timestamptz;
  v_desde  date;
  v_hasta  date;
  v_ini    timestamptz;
  v_fin    timestamptz;
begin
  select p.super_usuario into v_super
    from public.perfil p
   where p.id = auth.uid();

  if coalesce(v_super, false) is not true then
    raise exception 'No autorizado: fn_reporte_actividad requiere super_usuario';
  end if;

  -- Salida a produccion: 03/09/2026 11:20 a.m. hora de Lima.
  v_corte := (timestamp '2026-09-03 11:20:00') at time zone 'America/Lima';

  v_hasta := coalesce(p_hasta, fn_hoy());
  v_desde := coalesce(p_desde, v_hasta - 30);

  v_ini := greatest((v_desde::timestamp) at time zone 'America/Lima', v_corte);
  v_fin := ((v_hasta + 1)::timestamp)    at time zone 'America/Lima';

  return query
  with evt as (
    -- Un solo flujo de eventos: bitacora + avances, ya recortado a la ventana.
    -- usuario_id is not null deja fuera las filas que escribe el trigger de
    -- puntaje, que no tienen persona detras.
    select b.usuario_id      as uid,
           b.fecha_registro  as ts,
           b.campo           as campo,
           b.id_compromiso   as idc
      from public.bitacora b
     where b.usuario_id is not null
       and b.fecha_registro >= v_ini
       and b.fecha_registro <  v_fin
    union all
    select ca.registrado_por as uid,
           ca.registrado_en  as ts,
           '_avance_'        as campo,
           ca.id_compromiso  as idc
      from public.compromiso_avance ca
     where ca.registrado_por is not null
       and ca.registrado_en >= v_ini
       and ca.registrado_en <  v_fin
  ),
  acc as (
    select distinct on (e.uid) e.uid, e.ts, e.campo, e.idc
      from evt e
     order by e.uid, e.ts desc
  ),
  det as (
    select a.uid,
           a.ts,
           (case a.campo
              when '_avance_'             then 'Registró un avance'
              when 'estado'               then 'Cambió el estado'
              when 'comentario'           then 'Escribió un comentario'
              when 'comentario_final'     then 'Escribió comentario de revisión'
              when 'rutaArchivos'         then 'Adjuntó archivos'
              when 'fechaEntregaReal'     then 'Registró la fecha real de entrega'
              when 'fechaEntrega_anterior' then 'Cambió la fecha de entrega'
              when 'validacion'           then 'Validó una tarea'
              when 'creacion'             then 'Creó una tarea'
              else coalesce(a.campo, 'Actualizó una tarea')
            end)
           || coalesce(' · ' || case when coalesce(c.confidencial, false)
                                     then '(confidencial)'   -- sin ID, por decision
                                     else a.idc end, '')     as detalle
      from acc a
      left join public.compromiso c on c.id_compromiso = a.idc
  ),
  ar as (
    select pa.perfil_id                                                as uid,
           string_agg(pa.area_prefijo, ' | ' order by pa.area_prefijo) as lista
      from public.perfil_area pa
     group by pa.perfil_id
  ),
  base as (
    select p.usuario,
           p.nombre_completo,
           p.rol_id,
           p.empresa_id,
           coalesce(ar.lista, '-')                                     as areas,
           p.activo,
           p.password_cambiado,
           -- lo anterior al corte es etapa de prueba: no se muestra.
           case when u.last_sign_in_at >= v_corte
                then u.last_sign_in_at end                             as ultimo_login,
           case when p.ultimo_acceso   >= v_corte
                then p.ultimo_acceso   end                             as ultimo_ping,
           d.ts                                                        as ultima_accion,
           d.detalle                                                   as ultima_accion_detalle
      from public.perfil p
      left join auth.users u on u.id   = p.id
      left join det d        on d.uid  = p.id
      left join ar           on ar.uid = p.id
  )
  select b.usuario,
         b.nombre_completo,
         b.rol_id,
         b.empresa_id,
         b.areas,
         b.activo,
         b.password_cambiado,
         b.ultimo_login,
         b.ultimo_ping,
         b.ultima_accion,
         b.ultima_accion_detalle,
         case when b.ultima_accion is null then null
              else (fn_hoy() - (b.ultima_accion at time zone 'America/Lima')::date)
         end::integer                                                  as dias_sin_actividad,
         case
           when b.ultimo_login is null and b.ultimo_ping is null       then 'NUNCA INGRESO'
           when b.ultima_accion is null                                then 'SIN MOVIMIENTO'
           when (fn_hoy() - (b.ultima_accion at time zone 'America/Lima')::date) <= 7  then 'ACTIVO'
           when (fn_hoy() - (b.ultima_accion at time zone 'America/Lima')::date) <= 30 then 'TIBIO'
           else 'INACTIVO'
         end                                                           as semaforo
    from base b
   order by (b.ultimo_login is null and b.ultimo_ping is null) desc,
            (b.ultima_accion is null)                          desc,
            b.ultima_accion asc nulls first,
            b.usuario       asc;
end;
$$;


ALTER FUNCTION public.fn_reporte_actividad(p_desde date, p_hasta date) OWNER TO postgres;

--
-- Name: fn_reproceso(text, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_reproceso(p_id text, p_comentario text, p_nueva_fecha date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_emp   text;
  v_lote  uuid;
  v_nresp smallint;
  v_asig  uuid;
begin
  select c.empresa_id, c.id_lote, c.n_responsables, c.asignado_por_id
    into v_emp, v_lote, v_nresp, v_asig
    from compromiso c where c.id_compromiso = p_id;

  if v_emp is null then
    raise exception 'Compromiso % no existe', p_id;
  end if;
  if not app_puede_cerrar_en(v_emp, v_asig) then
    raise exception 'No autorizado para mandar a reproceso en esta empresa (%)', v_emp;
  end if;
  if p_nueva_fecha is null then
    raise exception 'Debes indicar la nueva fecha de entrega';
  end if;

  perform set_config('app.fn_bypass', '1', true);
  perform set_config('app.lote_sync', '1', true);

  update compromiso set
    reprocesos         = reprocesos + 1,
    estado_avance_cod  = 'REPROCESO',
    estado_final_cod   = 'REPROCESO',
    comentario_final   = p_comentario,
    fecha_entrega_real = null,
    fecha_entrega      = p_nueva_fecha,
    check_analista = false, check_analista_por = null, check_analista_en = null,
    check_blesola  = false, check_blesola_por  = null, check_blesola_en  = null,
    check_fermet   = false, check_fermet_por   = null, check_fermet_en   = null,
    fecha_actualizacion_final = now()
  where id_compromiso = p_id
     or (v_lote is not null and v_nresp > 1 and id_lote = v_lote
         and estado_avance_cod <> 'INACTIVO');

  perform set_config('app.fn_bypass', '', true);
  perform set_config('app.lote_sync', '', true);
end $$;


ALTER FUNCTION public.fn_reproceso(p_id text, p_comentario text, p_nueva_fecha date) OWNER TO postgres;

--
-- Name: fn_responsables_lote(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_responsables_lote(p_id_lote uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_txt text;
begin
  -- fail-closed: sin sesion no devuelve nada (JWT vencido -> auth.uid() NULL)
  if auth.uid() is null then return null; end if;
  if p_id_lote is null then return null; end if;

  -- Guarda: al ser SECURITY DEFINER esta funcion salta el RLS. Solo responde a
  -- quien pertenece al lote o a quien ya ve todo por gestion. Sin esto,
  -- cualquiera podria llamarla con id_lote ajenos y cosechar nombres.
  if not (
    app_es_gestion()
    or exists (select 1 from compromiso c
                where c.id_lote = p_id_lote
                  and c.responsable_id = auth.uid())
  ) then
    return null;
  end if;

  select string_agg(pr.nombre_completo, ', ' order by pr.nombre_completo)
    into v_txt
    from compromiso c
    join perfil pr on pr.id = c.responsable_id
   where c.id_lote = p_id_lote
     and c.estado_avance_cod <> 'INACTIVO';

  return v_txt;
end $$;


ALTER FUNCTION public.fn_responsables_lote(p_id_lote uuid) OWNER TO postgres;

--
-- Name: fn_restaurar_tarea(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_restaurar_tarea(p_id text, p_estado text DEFAULT 'EN_PROCESO'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_admin  boolean;
  v_usuario text;
  v_estado text;
BEGIN
  SELECT super_usuario, usuario INTO v_admin, v_usuario FROM perfil WHERE id = v_caller;
  IF COALESCE(v_admin, false) <> true THEN
    RAISE EXCEPTION 'Solo el superusuario puede restaurar tareas.';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM estado_avance WHERE cod = p_estado) THEN
    RAISE EXCEPTION 'Estado % no existe en el catálogo.', p_estado;
  END IF;

  SELECT estado_avance_cod INTO v_estado FROM compromiso WHERE id_compromiso = p_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'La tarea % no existe.', p_id;
  END IF;
  IF v_estado <> 'INACTIVO' THEN
    RAISE EXCEPTION 'La tarea % no está anulada (estado actual: %).', p_id, v_estado;
  END IF;

  UPDATE compromiso SET
    estado_avance_cod = p_estado,
    comentario_final  = COALESCE(comentario_final, '') || E'\n'
                     || '♻️ RESTAURADA por ' || COALESCE(v_usuario, '?')
                     || ' el ' || to_char(now() AT TIME ZONE 'America/Lima', 'DD/MM/YYYY HH24:MI'),
    fecha_actualizacion_final = now()
  WHERE id_compromiso = p_id;

  RETURN json_build_object('ok', true, 'id', p_id, 'estado', p_estado);
END;
$$;


ALTER FUNCTION public.fn_restaurar_tarea(p_id text, p_estado text) OWNER TO postgres;

--
-- Name: fn_ruta_final(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_ruta_final(p_desde integer DEFAULT 0, p_limite integer DEFAULT 20000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'staging', 'pg_temp'
    AS $$
declare
    v_out jsonb;
begin
    -- Guarda: el botón está oculto para no-admins, pero la llave anon
    -- viaja en el HTML. Quien decide es esta línea, no el front.
    if not coalesce((select p.super_usuario
                     from public.perfil p
                     where p.id = auth.uid()), false) then
        raise exception
            'No autorizado: la exportación de ruta comercial es solo para administradores'
            using errcode = '42501';
    end if;

    if p_desde  is null or p_desde  < 0                      then p_desde  := 0;     end if;
    if p_limite is null or p_limite < 1 or p_limite > 50000   then p_limite := 20000; end if;

    with pag as (
        select subfase, cliente, n_cot, n_op, fecha, hora, estado, codigo,
               cantidad, unidad, categoria, material, precio_sin_igv, margen
        from public.vw_ruta_final_export
        order by fecha nulls last, n_op nulls last, hora nulls last
        offset p_desde
        limit  p_limite
    )
    select coalesce(
             jsonb_agg(to_jsonb(pag)
                       order by pag.fecha nulls last,
                                pag.n_op  nulls last,
                                pag.hora  nulls last),
             '[]'::jsonb)
      into v_out
      from pag;

    return v_out;
end;
$$;


ALTER FUNCTION public.fn_ruta_final(p_desde integer, p_limite integer) OWNER TO postgres;

--
-- Name: fn_siguiente_id(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_siguiente_id(p_area text, p_empresa text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_max int;
begin
  select coalesce(max((regexp_match(id_compromiso, '^' || p_area || '-(\d+)-' || p_empresa || '$'))[1]::int), 0)
    into v_max
  from compromiso
  where id_compromiso like p_area || '-%-' || p_empresa;

  return p_area || '-' || lpad((v_max + 1)::text, 3, '0') || '-' || p_empresa;
end $_$;


ALTER FUNCTION public.fn_siguiente_id(p_area text, p_empresa text) OWNER TO postgres;

--
-- Name: fn_sin_puntaje(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_sin_puntaje(p_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_emp     text;
  v_creador uuid;
  v_actual  smallint;
  v_lote    uuid;
  v_nresp   int;
begin
  select c.empresa_id, c.creado_por_id, c.puntaje_base, c.id_lote,
         coalesce(c.n_responsables, 1)
    into v_emp, v_creador, v_actual, v_lote, v_nresp
    from compromiso c
   where c.id_compromiso = p_id;

  if v_emp is null then
    raise exception 'La tarea % no existe', p_id;
  end if;

  -- Misma escalera de permisos que fn_puntuar. La tercera rama (quien registro
  -- la tarea) exige v_actual is null: marcar "sin puntaje" es parte del acto de
  -- asignar, no una correccion posterior.
  if not (
       app_es_admin()
    or (app_edita_puntaje()
        and (app_puntaje_empresa() = 'TODAS' or app_puntaje_empresa() = v_emp))
    or (v_creador = auth.uid() and v_actual is null and app_puede_asignar_a(v_emp))
  ) then
    raise exception 'No autorizado para marcar sin puntaje tareas de la empresa %', v_emp;
  end if;

  perform set_config('app.fn_bypass', '1', true);

  update compromiso c set
    puntaje_base         = 0,
    rubrica              = null,
    puntaje_validado     = true,
    puntaje_validado_por = auth.uid(),
    puntaje_validado_en  = now()
  where c.estado_avance_cod <> 'INACTIVO'
    and ( c.id_compromiso = p_id
       or (v_nresp > 1 and v_lote is not null and c.id_lote = v_lote) );

  perform set_config('app.fn_bypass', '', true);
end $$;


ALTER FUNCTION public.fn_sin_puntaje(p_id text) OWNER TO postgres;

--
-- Name: fn_validar_puntaje(text, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_validar_puntaje(p_id text, q1 integer DEFAULT NULL::integer, q2 integer DEFAULT NULL::integer, q3 integer DEFAULT NULL::integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_antes   smallint;
  v_despues smallint;
  v_lote    uuid;
  v_nresp   int;
  v_filas   int;
begin
  if not public.app_edita_puntaje() then
    raise exception 'No tienes permiso para validar puntajes';
  end if;

  select puntaje_base, id_lote, coalesce(n_responsables,1)
    into v_antes, v_lote, v_nresp
    from compromiso
   where id_compromiso = p_id;

  if not found then
    raise exception 'La tarea % no existe', p_id;
  end if;

  if q1 is not null and q2 is not null and q3 is not null then
    if q1 not in (10,20,30,40,50)
    or q2 not in (10,20,30,40,50)
    or q3 not in (10,20,30,40,50) then
      raise exception 'Cada respuesta debe ser 10, 20, 30, 40 o 50';
    end if;
    perform public.fn_puntuar(p_id, q1, q2, q3);
  end if;

  -- FIX MIG. 28 · misma cláusula de lote que fn_puntuar y fn_registrar_vb.
  update compromiso c
     set puntaje_validado     = true,
         puntaje_validado_por = auth.uid(),
         puntaje_validado_en  = now()
   where c.estado_avance_cod <> 'INACTIVO'
     and ( c.id_compromiso = p_id
        or (v_nresp > 1 and v_lote is not null and c.id_lote = v_lote) );

  get diagnostics v_filas = row_count;

  -- El puntaje quedó reescrito por fn_puntuar: se relee, no se usa RETURNING
  -- (con varias filas devolvía una cualquiera del lote).
  select puntaje_base into v_despues
    from compromiso where id_compromiso = p_id;

  begin
    insert into bitacora (id_compromiso, campo, valor, usuario_txt)
    values (
      p_id, 'puntaje',
      case when v_antes is distinct from v_despues
           then 'Puntaje ajustado de ' || coalesce(v_antes::text,'sin puntaje') ||
                ' a ' || coalesce(v_despues::text,'—') || ' y validado'
           else 'Puntaje ' || coalesce(v_despues::text,'—') || ' validado sin cambios' end
      || case when v_filas > 1
              then ' (tarea grupal · ' || v_filas || ' responsables)' else '' end,
      (select nombre_completo from perfil where id = auth.uid())
    );
  exception when others then
    null;
  end;
end $$;


ALTER FUNCTION public.fn_validar_puntaje(p_id text, q1 integer, q2 integer, q3 integer) OWNER TO postgres;

--
-- Name: trg_avance_hist(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_avance_hist() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(current_setting('app.lote_sync', true), '') = '1' then
    return new;
  end if;
  if TG_OP = 'UPDATE'
     and new.estado_avance_cod     is not distinct from old.estado_avance_cod
     and new.comentario_compromiso is not distinct from old.comentario_compromiso
     and new.ruta_archivo          is not distinct from old.ruta_archivo then
    return new;
  end if;
  insert into compromiso_avance(id_compromiso, estado_cod, comentario, ruta_archivo, registrado_por)
  values (new.id_compromiso, new.estado_avance_cod, new.comentario_compromiso, new.ruta_archivo, auth.uid());
  return new;
end $$;


ALTER FUNCTION public.trg_avance_hist() OWNER TO postgres;

--
-- Name: trg_bitacora_compromiso(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_bitacora_compromiso() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if coalesce(current_setting('app.lote_sync', true), '') = '1' then
    return new;
  end if;

  if TG_OP = 'INSERT' then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'creacion', new.detalle_compromiso);
    return new;
  end if;

  if new.estado_avance_cod is distinct from old.estado_avance_cod then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'estado', new.estado_avance_cod);
  end if;
  if new.comentario_compromiso is distinct from old.comentario_compromiso then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'comentario', new.comentario_compromiso);
  end if;

  -- ── v26 · NUEVO · comentario de revisión ──────────────────────────
  -- Se archiva cada versión. Se ignora el paso a vacío (limpieza) para no
  -- ensuciar el historial con movimientos sin contenido: el frontend ya
  -- filtra los valores vacíos, pero conviene no insertarlos siquiera.
  if new.comentario_final is distinct from old.comentario_final
     and coalesce(btrim(new.comentario_final), '') <> '' then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'comentario_final', new.comentario_final);
  end if;
  -- ──────────────────────────────────────────────────────────────────

  if new.ruta_archivo is distinct from old.ruta_archivo then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'rutaArchivos', new.ruta_archivo);
  end if;
  if new.fecha_entrega_real is distinct from old.fecha_entrega_real then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso,
            case when new.fecha_entrega_real is null
                 then 'fechaEntregaReal_borrada' else 'fechaEntregaReal' end,
            coalesce(new.fecha_entrega_real::text, old.fecha_entrega_real::text));
  end if;
  if new.fecha_entrega is distinct from old.fecha_entrega then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'fechaEntrega_anterior', old.fecha_entrega::text);
  end if;
  if new.reprocesos is distinct from old.reprocesos then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'reproceso', new.reprocesos::text);
  end if;
  if new.check_analista is distinct from old.check_analista then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'VB', case when new.check_analista then 'VB-A' else 'VB-A retirado' end);
  end if;
  if new.check_blesola is distinct from old.check_blesola then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'checkBlesola', new.check_blesola::text);
  end if;
  if new.check_fermet is distinct from old.check_fermet then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'checkFermet', new.check_fermet::text);
  end if;
  if new.puntaje_base is distinct from old.puntaje_base then
    insert into bitacora(usuario_id, id_compromiso, campo, valor)
    values (v_uid, new.id_compromiso, 'validacion', coalesce(new.rubrica,'') || ' → ' || coalesce(new.puntaje_base::text,''));
  end if;
  return new;
end $$;


ALTER FUNCTION public.trg_bitacora_compromiso() OWNER TO postgres;

--
-- Name: trg_fecha_entrega_real(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_fecha_entrega_real() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.estado_avance_cod = 'REALIZADO'
     and coalesce(old.estado_avance_cod,'') <> 'REALIZADO' then
    new.fecha_entrega_real := fn_hoy();          -- era current_date (UTC)
  elsif new.estado_avance_cod is distinct from 'REALIZADO'
     and coalesce(old.estado_avance_cod,'') = 'REALIZADO' then
    new.fecha_entrega_real := null;
  end if;
  return new;
end $$;


ALTER FUNCTION public.trg_fecha_entrega_real() OWNER TO postgres;

--
-- Name: trg_lote_sync(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_lote_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.id_lote is null or new.n_responsables <= 1 then
    return null;
  end if;
  if coalesce(current_setting('app.lote_sync', true), '') = '1' then
    return null;
  end if;
  if new.estado_avance_cod     is not distinct from old.estado_avance_cod
 and new.comentario_compromiso is not distinct from old.comentario_compromiso
 and new.ruta_archivo          is not distinct from old.ruta_archivo then
    return null;
  end if;

  perform set_config('app.lote_sync', '1', true);

  update compromiso c
     set estado_avance_cod     = new.estado_avance_cod,
         comentario_compromiso = new.comentario_compromiso,
         ruta_archivo          = new.ruta_archivo,
         fecha_ult_actualizacion = new.fecha_ult_actualizacion
   where c.id_lote = new.id_lote
     and c.id_compromiso <> new.id_compromiso
     and c.estado_avance_cod <> 'INACTIVO';
  -- fecha_entrega_real no se copia: trg_fecha_entrega_real la calcula sola
  -- en cada fila al ver el cambio de estado.

  perform set_config('app.lote_sync', '', true);
  return null;
end $$;


ALTER FUNCTION public.trg_lote_sync() OWNER TO postgres;

--
-- Name: trg_puntaje_reset(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_puntaje_reset() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.puntaje_base is distinct from old.puntaje_base
     and new.puntaje_validado = old.puntaje_validado then
    new.puntaje_validado     := false;
    new.puntaje_validado_por := null;
    new.puntaje_validado_en  := null;
  end if;
  return new;
end $$;


ALTER FUNCTION public.trg_puntaje_reset() OWNER TO postgres;

--
-- Name: trg_touch(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_touch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.actualizado_en := now();
  return new;
end $$;


ALTER FUNCTION public.trg_touch() OWNER TO postgres;

--
-- Name: trg_update_guard(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.trg_update_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if coalesce(current_setting('app.fn_bypass', true), '') = '1' then
    return new;
  end if;
  if app_es_admin() then
    return new;
  end if;

  if new.id_compromiso        is distinct from old.id_compromiso
  or new.id_lote              is distinct from old.id_lote
  or new.empresa_id           is distinct from old.empresa_id
  or new.area_prefijo         is distinct from old.area_prefijo
  or new.responsable_id       is distinct from old.responsable_id
  or new.asignado_por_id      is distinct from old.asignado_por_id
  or new.creado_por_id        is distinct from old.creado_por_id
  or new.confidencial         is distinct from old.confidencial
  or new.detalle_compromiso   is distinct from old.detalle_compromiso
  or new.nombre_tema          is distinct from old.nombre_tema
  or new.fecha_asignada       is distinct from old.fecha_asignada
  or new.fecha_entrega        is distinct from old.fecha_entrega
  or new.n_responsables       is distinct from old.n_responsables
  or new.reprocesos           is distinct from old.reprocesos
  then
    raise exception 'No autorizado: solo el Administrador modifica los datos base de la tarea';
  end if;

  if (new.puntaje_base    is distinct from old.puntaje_base
   or new.rubrica         is distinct from old.rubrica
   or new.puntaje_validado is distinct from old.puntaje_validado)
   and not (app_edita_puntaje()
            and (app_puntaje_empresa() = 'TODAS'
              or app_puntaje_empresa() = new.empresa_id)) then
    raise exception 'No autorizado: no puedes editar el puntaje de esta empresa';
  end if;

  return new;
end $$;


ALTER FUNCTION public.trg_update_guard() OWNER TO postgres;

--
-- Name: apply_rls(jsonb, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer DEFAULT (1024 * 1024)) RETURNS SETOF realtime.wal_rls
    LANGUAGE plpgsql
    AS $$
declare
    -- Regclass of the table e.g. public.notes
    entity_ regclass = (quote_ident(wal ->> 'schema') || '.' || quote_ident(wal ->> 'table'))::regclass;

    -- I, U, D, T: insert, update ...
    action realtime.action = (
        case wal ->> 'action'
            when 'I' then 'INSERT'
            when 'U' then 'UPDATE'
            when 'D' then 'DELETE'
            else 'ERROR'
        end
    );

    -- Is row level security enabled for the table
    is_rls_enabled bool = relrowsecurity from pg_class where oid = entity_;

    subscriptions realtime.subscription[] = array_agg(subs)
        from
            realtime.subscription subs
        where
            subs.entity = entity_
            -- Filter by action early - only get subscriptions interested in this action
            -- action_filter column can be: '*' (all), 'INSERT', 'UPDATE', or 'DELETE'
            and (subs.action_filter = '*' or subs.action_filter = action::text);

    -- Subscription vars
    working_role regrole;
    working_selected_columns text[];
    claimed_role regrole;
    claims jsonb;

    subscription_id uuid;
    subscription_has_access bool;
    visible_to_subscription_ids uuid[] = '{}';

    -- structured info for wal's columns
    columns realtime.wal_column[];
    -- previous identity values for update/delete
    old_columns realtime.wal_column[];

    error_record_exceeds_max_size boolean = octet_length(wal::text) > max_record_bytes;

    -- Primary jsonb output for record
    output jsonb;

    -- Loop record for iterating unique roles (outer loop)
    role_record record;
    -- Loop record for iterating unique selected_columns within a role (inner loop)
    cols_record record;
    -- Subscription ids visible at the role level (before fanning out by selected_columns)
    visible_role_sub_ids uuid[] = '{}';

begin
    perform set_config('role', null, true);

    columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'columns') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    old_columns =
        array_agg(
            (
                x->>'name',
                x->>'type',
                x->>'typeoid',
                realtime.cast(
                    (x->'value') #>> '{}',
                    coalesce(
                        (x->>'typeoid')::regtype, -- null when wal2json version <= 2.4
                        (x->>'type')::regtype
                    )
                ),
                (pks ->> 'name') is not null,
                true
            )::realtime.wal_column
        )
        from
            jsonb_array_elements(wal -> 'identity') x
            left join jsonb_array_elements(wal -> 'pk') pks
                on (x ->> 'name') = (pks ->> 'name');

    for role_record in
        select claims_role
        from (select distinct claims_role from unnest(subscriptions)) t
        order by claims_role::text
    loop
        working_role := role_record.claims_role;

        -- Update `is_selectable` for columns and old_columns (once per role)
        columns =
            array_agg(
                (
                    c.name,
                    c.type_name,
                    c.type_oid,
                    c.value,
                    c.is_pkey,
                    pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                )::realtime.wal_column
            )
            from
                unnest(columns) c;

        old_columns =
                array_agg(
                    (
                        c.name,
                        c.type_name,
                        c.type_oid,
                        c.value,
                        c.is_pkey,
                        pg_catalog.has_column_privilege(working_role, entity_, c.name, 'SELECT')
                    )::realtime.wal_column
                )
                from
                    unnest(old_columns) c;

        if action <> 'DELETE' and count(1) = 0 from unnest(columns) c where c.is_pkey then
            -- Fan out 400 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 400: Bad Request, no primary key']
                )::realtime.wal_rls;
            end loop;

        -- The claims role does not have SELECT permission to the primary key of entity
        elsif action <> 'DELETE' and sum(c.is_selectable::int) <> count(1) from unnest(columns) c where c.is_pkey then
            -- Fan out 401 error per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;
                return next (
                    jsonb_build_object(
                        'schema', wal ->> 'schema',
                        'table', wal ->> 'table',
                        'type', action
                    ),
                    is_rls_enabled,
                    (select array_agg(s.subscription_id) from unnest(subscriptions) as s where s.claims_role = working_role and (s.selected_columns is not distinct from working_selected_columns)),
                    array['Error 401: Unauthorized']
                )::realtime.wal_rls;
            end loop;

        else
            -- Create the prepared statement (once per role)
            if is_rls_enabled and action <> 'DELETE' then
                if (select 1 from pg_prepared_statements where name = 'walrus_rls_stmt' limit 1) > 0 then
                    deallocate walrus_rls_stmt;
                end if;
                execute realtime.build_prepared_statement_sql('walrus_rls_stmt', entity_, columns);
            end if;

            -- Collect all visible subscription IDs for this role (filter check + RLS check)
            visible_role_sub_ids = '{}';

            for subscription_id, claims in (
                    select
                        subs.subscription_id,
                        subs.claims
                    from
                        unnest(subscriptions) subs
                    where
                        subs.entity = entity_
                        and subs.claims_role = working_role
                        and (
                            realtime.is_visible_through_filters(columns, subs.filters)
                            or (
                              action = 'DELETE'
                              and realtime.is_visible_through_filters(old_columns, subs.filters)
                            )
                        )
            ) loop

                if not is_rls_enabled or action = 'DELETE' then
                    visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                else
                    -- Check if RLS allows the role to see the record
                    perform
                        -- Trim leading and trailing quotes from working_role because set_config
                        -- doesn't recognize the role as valid if they are included
                        set_config('role', trim(both '"' from working_role::text), true),
                        set_config('request.jwt.claims', claims::text, true);

                    execute 'execute walrus_rls_stmt' into subscription_has_access;

                    -- Reset the role on every FOR..LOOP batch execution.
                    -- The first batch of 10 rows is pre-fetched using the current connection role (PG internal behaviour)
                    -- then we have to reset it again otherwise it would use the role defined in the `set_config` above
                    -- to fetch the remaining rows when rows>10, which could be a user-defined role that lacks execution grants.
                    -- The flow is:
                    --   1. run batch with conn role
                    --   2. set_config working_role
                    --   3. execute walrus
                    --   4. reset role (revert)
                    --   5. repeat
                    perform set_config('role', null, true);

                    if subscription_has_access then
                        visible_role_sub_ids = visible_role_sub_ids || subscription_id;
                    end if;
                end if;
            end loop;

            perform set_config('role', null, true);

            -- Inner loop: per distinct selected_columns for this role
            for cols_record in
                select selected_columns
                from (select distinct selected_columns from unnest(subscriptions) s where s.claims_role = working_role) t
                order by coalesce(array_to_string(selected_columns, ','), '')
            loop
                working_selected_columns := cols_record.selected_columns;

                output = jsonb_build_object(
                    'schema', wal ->> 'schema',
                    'table', wal ->> 'table',
                    'type', action,
                    'commit_timestamp', to_char(
                        ((wal ->> 'timestamp')::timestamptz at time zone 'utc'),
                        'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'
                    ),
                    'columns', (
                        select
                            jsonb_agg(
                                jsonb_build_object(
                                    'name', pa.attname,
                                    'type', pt.typname
                                )
                                order by pa.attnum asc
                            )
                        from
                            pg_attribute pa
                            join pg_type pt
                                on pa.atttypid = pt.oid
                            left join (
                                select unnest(conkey) as pkey_attnum
                                from pg_constraint
                                where conrelid = entity_ and contype = 'p'
                            ) pk on pk.pkey_attnum = pa.attnum
                        where
                            attrelid = entity_
                            and attnum > 0
                            and pg_catalog.has_column_privilege(working_role, entity_, pa.attname, 'SELECT')
                            and (working_selected_columns is null or pa.attname = any(working_selected_columns) or pk.pkey_attnum is not null)
                    )
                )
                -- Add "record" key for insert and update
                || case
                    when action in ('INSERT', 'UPDATE') then
                        jsonb_build_object(
                            'record',
                            (
                                select
                                    jsonb_object_agg(
                                        -- if unchanged toast, get column name and value from old record
                                        coalesce((c).name, (oc).name),
                                        case
                                            when (c).name is null then (oc).value
                                            else (c).value
                                        end
                                    )
                                from
                                    unnest(columns) c
                                    full outer join unnest(old_columns) oc
                                        on (c).name = (oc).name
                                where
                                    coalesce((c).is_selectable, (oc).is_selectable)
                                    and (working_selected_columns is null or coalesce((c).name, (oc).name) = any(working_selected_columns) or coalesce((c).is_pkey, (oc).is_pkey))
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                            )
                        )
                    else '{}'::jsonb
                end
                -- Add "old_record" key for update and delete
                || case
                    when action = 'UPDATE' then
                        jsonb_build_object(
                                'old_record',
                                (
                                    select jsonb_object_agg((c).name, (c).value)
                                    from unnest(old_columns) c
                                    where
                                        (c).is_selectable
                                        and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                        and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                )
                            )
                    when action = 'DELETE' then
                        jsonb_build_object(
                            'old_record',
                            (
                                select jsonb_object_agg((c).name, (c).value)
                                from unnest(old_columns) c
                                where
                                    (c).is_selectable
                                    and (working_selected_columns is null or (c).name = any(working_selected_columns) or (c).is_pkey)
                                    and ( not error_record_exceeds_max_size or (octet_length((c).value::text) <= 64))
                                    and ( not is_rls_enabled or (c).is_pkey ) -- if RLS enabled, we can't secure deletes so filter to pkey
                            )
                        )
                    else '{}'::jsonb
                end;

                -- Filter visible_role_sub_ids to those matching the current selected_columns group
                visible_to_subscription_ids = coalesce(
                    (
                        select array_agg(s.subscription_id)
                        from unnest(subscriptions) s
                        where s.claims_role = working_role
                          and (s.selected_columns is not distinct from working_selected_columns)
                          and s.subscription_id = any(visible_role_sub_ids)
                    ),
                    '{}'::uuid[]
                );

                return next (
                    output,
                    is_rls_enabled,
                    visible_to_subscription_ids,
                    case
                        when error_record_exceeds_max_size then array['Error 413: Payload Too Large']
                        else '{}'
                    end
                )::realtime.wal_rls;
            end loop;

        end if;
    end loop;

    perform set_config('role', null, true);
end;
$$;


ALTER FUNCTION realtime.apply_rls(wal jsonb, max_record_bytes integer) OWNER TO supabase_realtime_admin;

--
-- Name: broadcast_changes(text, text, text, text, text, record, record, text); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text DEFAULT 'ROW'::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Declare a variable to hold the JSONB representation of the row
    row_data jsonb := '{}'::jsonb;
BEGIN
    IF level = 'STATEMENT' THEN
        RAISE EXCEPTION 'function can only be triggered for each row, not for each statement';
    END IF;
    -- Check the operation type and handle accordingly
    IF operation = 'INSERT' OR operation = 'UPDATE' OR operation = 'DELETE' THEN
        row_data := jsonb_build_object('old_record', OLD, 'record', NEW, 'operation', operation, 'table', table_name, 'schema', table_schema);
        PERFORM realtime.send (row_data, event_name, topic_name);
    ELSE
        RAISE EXCEPTION 'Unexpected operation type: %', operation;
    END IF;
EXCEPTION
    WHEN OTHERS THEN
        RAISE EXCEPTION 'Failed to process the row: %', SQLERRM;
END;

$$;


ALTER FUNCTION realtime.broadcast_changes(topic_name text, event_name text, operation text, table_name text, table_schema text, new record, old record, level text) OWNER TO supabase_realtime_admin;

--
-- Name: build_prepared_statement_sql(text, regclass, realtime.wal_column[]); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) RETURNS text
    LANGUAGE sql
    AS $$
      /*
      Builds a sql string that, if executed, creates a prepared statement to
      tests retrive a row from *entity* by its primary key columns.
      Example
          select realtime.build_prepared_statement_sql('public.notes', '{"id"}'::text[], '{"bigint"}'::text[])
      */
          select
      'prepare ' || prepared_statement_name || ' as
          select
              exists(
                  select
                      1
                  from
                      ' || entity || '
                  where
                      ' || string_agg(quote_ident(pkc.name) || '=' || quote_nullable(pkc.value #>> '{}') , ' and ') || '
              )'
          from
              unnest(columns) pkc
          where
              pkc.is_pkey
          group by
              entity
      $$;


ALTER FUNCTION realtime.build_prepared_statement_sql(prepared_statement_name text, entity regclass, columns realtime.wal_column[]) OWNER TO supabase_realtime_admin;

--
-- Name: cast(text, regtype); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime."cast"(val text, type_ regtype) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare
  res jsonb;
begin
  if type_::text = 'bytea' then
    return to_jsonb(val);
  end if;
  execute format('select to_jsonb(%L::'|| type_::text || ')', val) into res;
  return res;
end
$$;


ALTER FUNCTION realtime."cast"(val text, type_ regtype) OWNER TO supabase_realtime_admin;

--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
/*
Casts *val_1* and *val_2* as type *type_* and check the *op* condition for truthiness
*/
declare
    op_symbol text = (
        case
            when op = 'eq' then '='
            when op = 'neq' then '!='
            when op = 'lt' then '<'
            when op = 'lte' then '<='
            when op = 'gt' then '>'
            when op = 'gte' then '>='
            when op = 'in' then '= any'
            else 'UNKNOWN OP'
        end
    );
    res boolean;
begin
    execute format(
        'select %L::'|| type_::text || ' ' || op_symbol
        || ' ( %L::'
        || (
            case
                when op = 'in' then type_::text || '[]'
                else type_::text end
        )
        || ')', val_1, val_2) into res;
    return res;
end;
$$;


ALTER FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text) OWNER TO supabase_realtime_admin;

--
-- Name: check_equality_op(realtime.equality_op, regtype, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
declare
    op_symbol text;
    res boolean;
begin
    -- IS DISTINCT FROM / IS NOT DISTINCT FROM: infix, both sides typed literals
    if op = 'isdistinct' then
        execute format(
            'select %L::%s %s %L::%s',
            val_1,
            type_::text,
            case when negate then 'IS NOT DISTINCT FROM' else 'IS DISTINCT FROM' end,
            val_2,
            type_::text
        ) into res;
        return res;
    end if;

    -- IS requires a keyword RHS (NULL, TRUE, FALSE, UNKNOWN), not a typed literal
    if op = 'is' then
        if val_2 not in ('null', 'true', 'false', 'unknown') then
            raise exception 'invalid value for is filter: must be null, true, false, or unknown';
        end if;
        execute format(
            'select %L::%s %s %s',
            val_1,
            type_::text,
            case when negate then 'IS NOT' else 'IS' end,
            upper(val_2)
        ) into res;
        return res;
    end if;

    op_symbol = case
        when op = 'eq'    then '='
        when op = 'neq'   then '!='
        when op = 'lt'    then '<'
        when op = 'lte'   then '<='
        when op = 'gt'    then '>'
        when op = 'gte'   then '>='
        when op = 'in'    then '= any'
        when op = 'like'   then 'LIKE'
        when op = 'ilike'  then 'ILIKE'
        when op = 'match'  then '~'
        when op = 'imatch' then '~*'
        else null
    end;

    if op_symbol is null then
        raise exception 'unsupported equality operator: %', op::text;
    end if;

    execute format(
        'select %L::%s %s (%L::%s)',
        val_1,
        type_::text,
        op_symbol,
        val_2,
        case when op = 'in' then type_::text || '[]' else type_::text end
    ) into res;

    return case when negate then not res else res end;
end;
$$;


ALTER FUNCTION realtime.check_equality_op(op realtime.equality_op, type_ regtype, val_1 text, val_2 text, negate boolean) OWNER TO supabase_realtime_admin;

--
-- Name: is_visible_through_filters(realtime.wal_column[], realtime.user_defined_filter[]); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    select
        filters is null
        or array_length(filters, 1) is null
        or coalesce(
            count(col.name) = count(1)
            and sum(
                realtime.check_equality_op(
                    op:=f.op,
                    type_:=coalesce(col.type_oid::regtype, col.type_name::regtype),
                    val_1:=col.value #>> '{}',
                    val_2:=f.value,
                    negate:=coalesce(f.negate, false)
                )::int
            ) filter (where col.name is not null) = count(col.name),
            false
        )
    from
        unnest(filters) f
        left join unnest(columns) col
            on f.column_name = col.name;
$$;


ALTER FUNCTION realtime.is_visible_through_filters(columns realtime.wal_column[], filters realtime.user_defined_filter[]) OWNER TO supabase_realtime_admin;

--
-- Name: list_changes(name, name, integer, integer); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) RETURNS TABLE(wal jsonb, is_rls_enabled boolean, subscription_ids uuid[], errors text[], slot_changes_count bigint)
    LANGUAGE sql
    SET log_min_messages TO 'fatal'
    AS $$
  WITH pub AS (
    SELECT
      concat_ws(
        ',',
        CASE WHEN bool_or(pubinsert) THEN 'insert' ELSE NULL END,
        CASE WHEN bool_or(pubupdate) THEN 'update' ELSE NULL END,
        CASE WHEN bool_or(pubdelete) THEN 'delete' ELSE NULL END
      ) AS w2j_actions,
      coalesce(
        string_agg(
          realtime.quote_wal2json(format('%I.%I', schemaname, tablename)::regclass),
          ','
        ) filter (WHERE ppt.tablename IS NOT NULL),
        ''
      ) AS w2j_add_tables
    FROM pg_publication pp
    LEFT JOIN pg_publication_tables ppt ON pp.pubname = ppt.pubname
    WHERE pp.pubname = publication
    GROUP BY pp.pubname
    LIMIT 1
  ),
  -- MATERIALIZED ensures pg_logical_slot_get_changes is called exactly once
  w2j AS MATERIALIZED (
    SELECT x.*, pub.w2j_add_tables
    FROM pub,
         pg_logical_slot_get_changes(
           slot_name, null, max_changes,
           'include-pk', 'true',
           'include-transaction', 'false',
           'include-timestamp', 'true',
           'include-type-oids', 'true',
           'format-version', '2',
           'actions', pub.w2j_actions,
           'add-tables', pub.w2j_add_tables
         ) x
  ),
  slot_count AS (
    SELECT count(*)::bigint AS cnt
    FROM w2j
    WHERE w2j.w2j_add_tables <> ''
  ),
  rls_filtered AS (
    SELECT xyz.wal, xyz.is_rls_enabled, xyz.subscription_ids, xyz.errors
    FROM w2j,
         realtime.apply_rls(
           wal := w2j.data::jsonb,
           max_record_bytes := max_record_bytes
         ) xyz(wal, is_rls_enabled, subscription_ids, errors)
    WHERE w2j.w2j_add_tables <> ''
      AND xyz.subscription_ids[1] IS NOT NULL
  )
  SELECT rf.wal, rf.is_rls_enabled, rf.subscription_ids, rf.errors, sc.cnt
  FROM rls_filtered rf, slot_count sc

  UNION ALL

  SELECT null, null, null, null, sc.cnt
  FROM slot_count sc
  WHERE NOT EXISTS (SELECT 1 FROM rls_filtered)
$$;


ALTER FUNCTION realtime.list_changes(publication name, slot_name name, max_changes integer, max_record_bytes integer) OWNER TO supabase_realtime_admin;

--
-- Name: quote_wal2json(regclass); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.quote_wal2json(entity regclass) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT
    realtime.wal2json_escape_identifier(nsp.nspname::text)
    || '.'
    || realtime.wal2json_escape_identifier(pc.relname::text)
  FROM pg_class pc
  JOIN pg_namespace nsp ON pc.relnamespace = nsp.oid
  WHERE pc.oid = entity
$$;


ALTER FUNCTION realtime.quote_wal2json(entity regclass) OWNER TO supabase_realtime_admin;

--
-- Name: send(jsonb, text, text, boolean); Type: FUNCTION; Schema: realtime; Owner: supabase_realtime_admin
--

CREATE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  generated_id uuid;
  final_payload jsonb;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    -- Check if payload has an 'id' key, if not, add the generated UUID
    IF payload ? 'id' THEN
      final_payload := payload;
    ELSE
      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));
    END IF;

    -- Set the topic configuration
    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)
    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$$;


ALTER FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean) OWNER TO supabase_realtime_admin;

