-- Name: try_cast(text, anyelement); Type: FUNCTION; Schema: staging; Owner: postgres
--

CREATE FUNCTION staging.try_cast(p_in text, p_tipo anyelement) RETURNS anyelement
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    IF p_in IS NULL OR btrim(p_in) = '' THEN
        RETURN NULL;
    END IF;
    EXECUTE format('SELECT %L::%s', btrim(p_in), pg_typeof(p_tipo)) INTO p_tipo;
    RETURN p_tipo;
EXCEPTION WHEN others THEN
    RETURN NULL;
END;
$$;


