--

CREATE FUNCTION staging.try_cast(p_in text, type regtype) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Ejecuta dinámicamente el cast básico de Postgres
    EXECUTE FORMAT('SELECT %L::%s;', p_in, type) INTO p_in;
    RETURN p_in;
EXCEPTION 
    WHEN others THEN 
        RETURN NULL; -- Si falla la conversión, devuelve NULL de forma segura
END;
$$;


