--
-- Name: v_compromiso; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_compromiso WITH (security_invoker='true') AS
 WITH base AS (
         SELECT c.id_compromiso,
            c.id_lote,
            c.es_masiva,
            c.id_acta,
            c.fecha_reunion,
            c.id_tema,
            c.nombre_tema,
            c.detalle_tema,
            c.proyecto_asociado,
            c.asignacion_compromiso,
            c.prioridad,
            c.area_prefijo,
            c.empresa_id,
            c.detalle_compromiso,
            c.responsable_id,
            c.asignado_por_id,
            c.creado_por_id,
            c.n_responsables,
            c.fecha_asignada,
            c.fecha_entrega,
            c.reunion_presencial,
            c.confidencial,
            c.estado_avance_cod,
            c.comentario_compromiso,
            c.ruta_archivo,
            c.fecha_ult_actualizacion,
            c.estado_final_cod,
            c.comentario_final,
            c.fecha_entrega_real,
            c.fecha_actualizacion_final,
            c.check_analista,
            c.check_analista_por,
            c.check_analista_en,
            c.check_blesola,
            c.check_blesola_por,
            c.check_blesola_en,
            c.check_fermet,
            c.check_fermet_por,
            c.check_fermet_en,
            c.rubrica,
            c.puntaje_base,
            c.reprocesos,
            c.fuera_fecha,
            c.puntaje_final,
            c.puntaje_persona,
            c.creado_en,
            c.actualizado_en,
            c.puntaje_validado,
            c.puntaje_validado_por,
            c.puntaje_validado_en,
                CASE
                    WHEN (c.estado_avance_cod = ANY (ARRAY['INACTIVO'::text, 'NO_APLICA'::text])) THEN 'NA'::text
                    WHEN (c.fecha_asignada > public.fn_hoy()) THEN 'PROGRAMADO'::text
                    WHEN (c.estado_avance_cod = 'REPROCESO'::text) THEN 'REPROCESO'::text
                    WHEN (c.estado_avance_cod = 'BLOQUEADO'::text) THEN 'BLOQUEADO'::text
                    WHEN (c.estado_avance_cod = 'REALIZADO'::text) THEN
                    CASE
                        WHEN ((COALESCE(c.estado_final_cod, ''::text) <> 'APROBADO'::text) AND (NOT c.check_analista)) THEN 'CERRADO_POR_APROBAR'::text
                        WHEN (c.fecha_entrega IS NULL) THEN 'CERRADO_PLAZO'::text
                        WHEN (c.fecha_entrega_real IS NULL) THEN 'CERRADO_PLAZO'::text
                        WHEN (c.fecha_entrega_real <= c.fecha_entrega) THEN 'CERRADO_PLAZO'::text
                        ELSE 'CERRADO_FUERA'::text
                    END
                    WHEN (c.fecha_entrega IS NULL) THEN 'NA'::text
                    WHEN (public.fn_hoy() > c.fecha_entrega) THEN 'VENCIDO'::text
                    WHEN (public.dias_lab((public.fn_hoy() + 1), c.fecha_entrega) <= 3) THEN 'POR_VENCER'::text
                    ELSE 'EN_PLAZO'::text
                END AS alerta_cod
           FROM public.compromiso c
        )
 SELECT b.id_compromiso,
    b.id_lote,
    b.id_acta,
    b.fecha_reunion,
    b.id_tema,
    b.nombre_tema,
    b.detalle_tema,
    b.proyecto_asociado,
    b.asignacion_compromiso,
    b.prioridad,
    b.area_prefijo,
    b.empresa_id,
    b.detalle_compromiso,
    b.responsable_id,
    b.asignado_por_id,
    b.fecha_asignada,
    b.fecha_entrega,
    b.reunion_presencial,
    b.confidencial,
    b.estado_avance_cod,
    b.comentario_compromiso,
    b.ruta_archivo,
    b.fecha_ult_actualizacion,
    b.estado_final_cod,
    b.comentario_final,
    b.fecha_entrega_real,
    b.fecha_actualizacion_final,
    b.check_analista,
    b.check_analista_por,
    b.check_analista_en,
    b.check_blesola,
    b.check_blesola_por,
    b.check_blesola_en,
    b.check_fermet,
    b.check_fermet_por,
    b.check_fermet_en,
    b.rubrica,
        CASE
            WHEN (b.puntaje_validado OR public.app_es_gestion() OR public.app_edita_puntaje()) THEN b.puntaje_base
            ELSE NULL::smallint
        END AS puntaje_base,
    b.reprocesos,
    b.fuera_fecha,
        CASE
            WHEN (b.puntaje_validado OR public.app_es_gestion() OR public.app_edita_puntaje()) THEN b.puntaje_final
            ELSE NULL::smallint
        END AS puntaje_final,
    b.creado_en,
    b.actualizado_en,
    b.alerta_cod,
    a.nombre AS area_nombre,
    e.nombre AS empresa_nombre,
    pr.nombre_completo AS responsable_nombre,
    pr.usuario AS responsable_usuario,
    pa.nombre_completo AS asignado_por_nombre,
    ea.nombre AS estado_avance_nombre,
    ef.nombre AS estado_final_nombre,
    al.nombre AS alerta_nombre,
    (b.check_analista AND (COALESCE(b.estado_avance_cod, ''::text) <> 'REPROCESO'::text)) AS cerrado,
    b.puntaje_validado,
    b.puntaje_validado_por,
    b.puntaje_validado_en,
    b.creado_por_id,
    b.n_responsables,
        CASE
            WHEN (b.puntaje_validado OR public.app_es_gestion() OR public.app_edita_puntaje()) THEN b.puntaje_persona
            ELSE NULL::smallint
        END AS puntaje_persona,
    pc.nombre_completo AS creado_por_nombre,
        CASE
            WHEN (b.puntaje_validado OR public.app_es_gestion() OR public.app_edita_puntaje()) THEN round(((b.puntaje_final)::numeric / (GREATEST(COALESCE((b.n_responsables)::integer, 1), 1))::numeric), 1)
            ELSE NULL::numeric
        END AS puntaje_persona_num,
        CASE
            WHEN ((b.id_lote IS NOT NULL) AND (COALESCE((b.n_responsables)::integer, 1) > 1)) THEN public.fn_responsables_lote(b.id_lote)
            ELSE NULL::text
        END AS responsables_lote,
    (b.fecha_asignada > public.fn_hoy()) AS es_programada,
    COALESCE(b.es_masiva, false) AS es_masiva
   FROM ((((((((base b
     JOIN public.area a ON ((a.prefijo = b.area_prefijo)))
     JOIN public.empresa e ON ((e.id_emp = b.empresa_id)))
     JOIN public.perfil pr ON ((pr.id = b.responsable_id)))
     LEFT JOIN public.perfil pa ON ((pa.id = b.asignado_por_id)))
     LEFT JOIN public.perfil pc ON ((pc.id = b.creado_por_id)))
     LEFT JOIN public.estado_avance ea ON ((ea.cod = b.estado_avance_cod)))
     LEFT JOIN public.estado_final ef ON ((ef.cod = b.estado_final_cod)))
     LEFT JOIN public.alerta al ON ((al.cod = b.alerta_cod)))
  WHERE ((public.app_alcance_ef() = 'TODAS'::text) OR (b.empresa_id = public.app_alcance_ef()));


ALTER VIEW public.v_compromiso OWNER TO postgres;

--
-- Name: v_export_gestion_areas; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_export_gestion_areas WITH (security_invoker='on') AS
 SELECT id_acta AS "ID_Acta",
    area_nombre AS "Area_grupo",
    to_char((fecha_reunion)::timestamp with time zone, 'DD/MM/YYYY'::text) AS "Fecha_Reunion",
    id_tema AS "ID_Tema",
    nombre_tema AS "Nombre_Tema",
    detalle_tema AS "Detalle_Tema",
    proyecto_asociado AS "Proyecto_Asociado",
    asignacion_compromiso AS "Asignación_compromiso",
    prioridad AS "Prioridad",
    id_compromiso AS "ID_Compromiso",
    detalle_compromiso AS "Detalle_Compromiso",
    responsable_nombre AS "Responsable_Empresa",
    to_char((fecha_asignada)::timestamp with time zone, 'DD/MM/YYYY'::text) AS "Fecha_Asignada",
    to_char((fecha_entrega)::timestamp with time zone, 'DD/MM/YYYY'::text) AS "Fecha_Entrega",
    estado_avance_nombre AS "Estado_compromiso",
    comentario_compromiso AS "Comentario_Compromiso",
    ruta_archivo AS "Ruta_Archivo",
    to_char(fecha_ult_actualizacion, 'DD/MM/YYYY HH24:MI'::text) AS "Fecha_ult_Actualización",
    alerta_nombre AS "Alerta",
    estado_final_nombre AS "Estado_Final",
    comentario_final AS "Comentario_Final",
    to_char((fecha_entrega_real)::timestamp with time zone, 'DD/MM/YYYY'::text) AS "Fecha_Entrega_real",
    to_char(fecha_actualizacion_final, 'DD/MM/YYYY HH24:MI'::text) AS "Fecha_Actualizacion_Final",
        CASE
            WHEN check_analista THEN '✅'::text
            ELSE ''::text
        END AS "Check_Analista",
        CASE
            WHEN check_blesola THEN '✅'::text
            ELSE ''::text
        END AS "Check_SubgBlesola",
        CASE
            WHEN check_fermet THEN '✅'::text
            ELSE ''::text
        END AS "Check_SubgFermet",
    asignado_por_nombre AS "Asignado_Por",
    rubrica AS "Rubrica",
    puntaje_base AS "Puntaje_Base",
    reprocesos AS "Reprocesos",
        CASE
            WHEN fuera_fecha THEN 1
            ELSE 0
        END AS "Fuera_fecha",
    puntaje_final AS "Puntaje_Final",
        CASE
            WHEN reunion_presencial THEN 'SI'::text
            ELSE ''::text
        END AS "Reunion_Presencial",
        CASE
            WHEN confidencial THEN 'SI'::text
            ELSE ''::text
        END AS "Confidencial"
   FROM public.v_compromiso v
  ORDER BY area_nombre, id_compromiso;


ALTER VIEW public.v_export_gestion_areas OWNER TO postgres;

--
-- Name: v_notif_pendiente; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_notif_pendiente WITH (security_invoker='on') AS
 SELECT n.fecha_ref,
    p.nombre_completo AS destinatario,
    p.email_notificacion AS correo,
    p.rol_id,
    n.tipo,
    n.motivo,
    n.empresa_id,
    n.id_compromiso,
    c.nombre_tema,
    c.fecha_entrega,
    c.confidencial,
    n.creado_en,
    n.enviado_en
   FROM ((public.notificacion_cola n
     JOIN public.perfil p ON ((p.id = n.destinatario_id)))
     LEFT JOIN public.compromiso c ON ((c.id_compromiso = n.id_compromiso)))
  ORDER BY n.fecha_ref DESC, p.nombre_completo, n.tipo;


ALTER VIEW public.v_notif_pendiente OWNER TO postgres;

--
-- Name: v_ranking_area; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_ranking_area AS
 WITH filas AS (
         SELECT c.id_compromiso,
            c.id_lote,
            c.area_prefijo,
            c.empresa_id,
            c.check_analista,
            c.estado_avance_cod,
            c.puntaje_validado,
            c.reprocesos,
            c.fuera_fecha,
            c.puntaje_base,
            c.puntaje_final,
            COALESCE((c.n_responsables)::integer, 1) AS n_resp,
                CASE
                    WHEN ((COALESCE((c.n_responsables)::integer, 1) > 1) AND (c.id_lote IS NOT NULL)) THEN ('L:'::text || (c.id_lote)::text)
                    ELSE ('C:'::text || c.id_compromiso)
                END AS k
           FROM public.compromiso c
          WHERE ((COALESCE(c.estado_avance_cod, ''::text) <> 'INACTIVO'::text) AND (COALESCE((c.puntaje_base)::integer, '-1'::integer) <> 0))
        ), grupo AS (
         SELECT f.k,
            f.area_prefijo,
            f.empresa_id,
            bool_or((f.check_analista AND (COALESCE(f.estado_avance_cod, ''::text) <> 'REPROCESO'::text))) AS cerrada,
            bool_or(f.puntaje_validado) AS validado,
            max(f.reprocesos) AS reprocesos,
            bool_or(f.fuera_fecha) AS fuera_fecha,
            bool_or((f.puntaje_base IS NULL)) AS sin_puntaje,
            bool_or(((f.puntaje_base IS NOT NULL) AND (NOT f.puntaje_validado))) AS sin_validar,
            (((max(f.puntaje_base))::numeric * (count(*))::numeric) / (GREATEST(max(f.n_resp), 1))::numeric) AS pb_grupo,
            (((max(f.puntaje_final))::numeric * (count(*))::numeric) / (GREATEST(max(f.n_resp), 1))::numeric) AS pf_grupo
           FROM filas f
          GROUP BY f.k, f.area_prefijo, f.empresa_id
        )
 SELECT g.area_prefijo,
    a.nombre AS area,
    g.empresa_id,
    count(*) AS tareas,
    count(*) FILTER (WHERE g.cerrada) AS cerradas,
    round(COALESCE(sum(g.pb_grupo) FILTER (WHERE (g.cerrada AND g.validado)), (0)::numeric), 1) AS puntaje_asignado,
    round(COALESCE(sum(g.pf_grupo) FILTER (WHERE (g.cerrada AND g.validado)), (0)::numeric), 1) AS puntaje_final_sum,
    COALESCE(sum(g.reprocesos) FILTER (WHERE (g.cerrada AND g.validado)), (0)::bigint) AS reprocesos,
    count(*) FILTER (WHERE (g.fuera_fecha AND g.cerrada AND g.validado)) AS fuera_fecha,
    count(*) FILTER (WHERE g.sin_puntaje) AS sin_puntaje,
    count(*) FILTER (WHERE g.sin_validar) AS sin_validar
   FROM (grupo g
     JOIN public.area a ON ((a.prefijo = g.area_prefijo)))
  GROUP BY g.area_prefijo, a.nombre, g.empresa_id;


ALTER VIEW public.v_ranking_area OWNER TO postgres;

