--
-- Name: vw_ruta_cotizacion; Type: VIEW; Schema: staging; Owner: postgres
--

CREATE VIEW staging.vw_ruta_cotizacion AS
 SELECT
        CASE
            WHEN (COALESCE(n_op, ''::text) = ''::text) THEN 'Cotizacion'::text
            ELSE 'Pedido-ventas'::text
        END AS subfase,
    cliente,
    staging.fmt_cot(n_cot) AS n_cot,
    staging.fmt_op(n_op) AS n_op,
    (staging.try_ts(_modificado_en))::date AS fecha,
    (staging.try_ts(_modificado_en))::time without time zone AS hora,
    estado_op AS estado,
    codigo,
    staging.try_cast(cantidad, NULL::numeric) AS cantidad,
    unidad,
    categoria,
    material,
    staging.try_cast(precio_sin_igv, NULL::numeric) AS precio_sin_igv,
    staging.try_cast(margen, NULL::numeric) AS margen
   FROM staging.sgt_cotizaciones t0
  WHERE ((COALESCE(n_cot, ''::text) <> ''::text) AND (COALESCE(codigo, ''::text) <> ''::text) AND (COALESCE(item, ''::text) <> ''::text) AND (COALESCE(estado_op, ''::text) = 'VENDIDO'::text));


ALTER VIEW staging.vw_ruta_cotizacion OWNER TO postgres;

--
-- Name: vw_ruta_cotizacion_cambio; Type: VIEW; Schema: staging; Owner: postgres
--

CREATE VIEW staging.vw_ruta_cotizacion_cambio AS
 SELECT DISTINCT 'Cotizacion'::text AS subfase,
    cliente,
    staging.fmt_cot(n_cot) AS n_cot,
    staging.fmt_op(n_op) AS n_op,
    (staging.try_ts(_modificado_en))::date AS fecha,
    (staging.try_ts(_modificado_en))::time without time zone AS hora,
    'PENDIENTE'::text AS estado,
    codigo,
    staging.try_cast(cantidad, NULL::numeric) AS cantidad,
    unidad,
    categoria,
    material,
    staging.try_cast(precio_sin_igv, NULL::numeric) AS precio_sin_igv,
    staging.try_cast(margen, NULL::numeric) AS margen
   FROM staging.hist_cotizaciones t0
  WHERE ((COALESCE(n_cot, ''::text) <> ''::text) AND (COALESCE(codigo, ''::text) <> ''::text) AND (COALESCE(item, ''::text) <> ''::text) AND (campo = 'estado_op'::text) AND (valor_anterior = 'PENDIENTE'::text));


ALTER VIEW staging.vw_ruta_cotizacion_cambio OWNER TO postgres;

--
-- Name: vw_ruta_pedido; Type: VIEW; Schema: staging; Owner: postgres
--

CREATE VIEW staging.vw_ruta_pedido AS
 SELECT t1.subfase,
    t0.cliente,
    staging.fmt_cot(ts.n_cot) AS n_cot,
    t0.n_op,
    (staging.try_ts(t1.fecha))::date AS fecha,
    (staging.try_ts(t1.fecha))::time without time zone AS hora,
        CASE
            WHEN (t1.subfase = 'VB Despacho'::text) THEN 'ATENDIDO'::text
            ELSE 'VENDIDO'::text
        END AS estado,
    NULL::text AS codigo,
    NULL::numeric AS cantidad,
    NULL::text AS unidad,
    NULL::text AS categoria,
    NULL::text AS material,
    NULL::numeric AS precio_sin_igv,
    NULL::numeric AS margen
   FROM ((staging.stg_pedidos t0
     LEFT JOIN ( SELECT sgt_cotizaciones.n_op,
            min(sgt_cotizaciones.n_cot) AS n_cot
           FROM staging.sgt_cotizaciones
          GROUP BY sgt_cotizaciones.n_op) ts ON ((t0.n_op = staging.fmt_op(ts.n_op))))
     CROSS JOIN LATERAL ( VALUES ('VB Logistica'::text,t0.vb_logistica,t0.fecha_hora_logistica), ('VB General'::text,t0.vb_general,t0.fecha_hora_general), ('VB Calidad'::text,t0.cert,t0.fecha_hora_cert), ('VB Despacho'::text,t0.vb_despacho,t0.fecha_despacho)) t1(subfase, flag_vb, fecha))
  WHERE ((COALESCE(t1.flag_vb, ''::text) <> ''::text) AND (COALESCE(t0.n_oc, ''::text) <> ''::text));


ALTER VIEW staging.vw_ruta_pedido OWNER TO postgres;

--
-- Name: vw_ruta_reserva; Type: VIEW; Schema: staging; Owner: postgres
--

CREATE VIEW staging.vw_ruta_reserva AS
 SELECT 'Reserva'::text AS subfase,
    ts.cliente,
    staging.fmt_cot(ts.n_cot) AS n_cot,
    t0.n_op,
    (staging.try_ts(t0.fecha_reserva))::date AS fecha,
    staging.try_hora(t0.hora_reserva) AS hora,
    'RESERVADO'::text AS estado,
    t0.codigo,
    staging.try_cast(t0.cantidad, NULL::numeric) AS cantidad,
    t0.unidad,
    NULL::text AS categoria,
    t0.material,
    NULL::numeric AS precio_sin_igv,
    NULL::numeric AS margen
   FROM (staging.stg_reserva t0
     LEFT JOIN ( SELECT sgt_cotizaciones.n_op,
            min(sgt_cotizaciones.n_cot) AS n_cot,
            min(sgt_cotizaciones.cliente) AS cliente
           FROM staging.sgt_cotizaciones
          GROUP BY sgt_cotizaciones.n_op) ts ON ((t0.n_op = staging.fmt_op(ts.n_op))))
  WHERE (COALESCE(t0.n_op, ''::text) <> ''::text);


ALTER VIEW staging.vw_ruta_reserva OWNER TO postgres;

--
-- Name: vw_ruta_final; Type: VIEW; Schema: staging; Owner: postgres
--

CREATE VIEW staging.vw_ruta_final AS
 SELECT vw_ruta_cotizacion_cambio.subfase,
    vw_ruta_cotizacion_cambio.cliente,
    vw_ruta_cotizacion_cambio.n_cot,
    vw_ruta_cotizacion_cambio.n_op,
    vw_ruta_cotizacion_cambio.fecha,
    vw_ruta_cotizacion_cambio.hora,
    vw_ruta_cotizacion_cambio.estado,
    vw_ruta_cotizacion_cambio.codigo,
    vw_ruta_cotizacion_cambio.cantidad,
    vw_ruta_cotizacion_cambio.unidad,
    vw_ruta_cotizacion_cambio.categoria,
    vw_ruta_cotizacion_cambio.material,
    vw_ruta_cotizacion_cambio.precio_sin_igv,
    vw_ruta_cotizacion_cambio.margen
   FROM staging.vw_ruta_cotizacion_cambio
UNION ALL
 SELECT vw_ruta_cotizacion.subfase,
    vw_ruta_cotizacion.cliente,
    vw_ruta_cotizacion.n_cot,
    vw_ruta_cotizacion.n_op,
    vw_ruta_cotizacion.fecha,
    vw_ruta_cotizacion.hora,
    vw_ruta_cotizacion.estado,
    vw_ruta_cotizacion.codigo,
    vw_ruta_cotizacion.cantidad,
    vw_ruta_cotizacion.unidad,
    vw_ruta_cotizacion.categoria,
    vw_ruta_cotizacion.material,
    vw_ruta_cotizacion.precio_sin_igv,
    vw_ruta_cotizacion.margen
   FROM staging.vw_ruta_cotizacion
UNION ALL
 SELECT vw_ruta_pedido.subfase,
    vw_ruta_pedido.cliente,
    vw_ruta_pedido.n_cot,
    vw_ruta_pedido.n_op,
    vw_ruta_pedido.fecha,
    vw_ruta_pedido.hora,
    vw_ruta_pedido.estado,
    vw_ruta_pedido.codigo,
    vw_ruta_pedido.cantidad,
    vw_ruta_pedido.unidad,
    vw_ruta_pedido.categoria,
    vw_ruta_pedido.material,
    vw_ruta_pedido.precio_sin_igv,
    vw_ruta_pedido.margen
   FROM staging.vw_ruta_pedido
UNION ALL
 SELECT vw_ruta_reserva.subfase,
    vw_ruta_reserva.cliente,
    vw_ruta_reserva.n_cot,
    vw_ruta_reserva.n_op,
    vw_ruta_reserva.fecha,
    vw_ruta_reserva.hora,
    vw_ruta_reserva.estado,
    vw_ruta_reserva.codigo,
    vw_ruta_reserva.cantidad,
    vw_ruta_reserva.unidad,
    vw_ruta_reserva.categoria,
    vw_ruta_reserva.material,
    vw_ruta_reserva.precio_sin_igv,
    vw_ruta_reserva.margen
   FROM staging.vw_ruta_reserva;


ALTER VIEW staging.vw_ruta_final OWNER TO postgres;

