--
-- Name: compromiso compromiso_insert_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY compromiso_insert_admin ON public.compromiso FOR INSERT TO authenticated WITH CHECK ((public.app_es_admin() OR public.app_puede_asignar()));


--
-- Name: compromiso compromiso_select; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY compromiso_select ON public.compromiso FOR SELECT TO authenticated USING ((((NOT confidencial) OR (responsable_id = auth.uid()) OR (asignado_por_id = auth.uid()) OR (creado_por_id = auth.uid()) OR public.app_ve_confidencial(empresa_id)) AND (public.app_es_gestion() OR public.app_ve_global() OR (responsable_id = auth.uid()) OR ((empresa_id = public.app_empresa()) AND (area_prefijo = ANY (public.app_areas())))) AND ((public.app_alcance_ef() = 'TODAS'::text) OR (empresa_id = public.app_alcance_ef())) AND ((fecha_asignada <= public.fn_hoy()) OR public.app_ve_programadas())));


--
-- Name: compromiso compromiso_update_admin; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY compromiso_update_admin ON public.compromiso FOR UPDATE TO authenticated USING (public.app_es_admin()) WITH CHECK (public.app_es_admin());


--
-- Name: compromiso compromiso_update_avance; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY compromiso_update_avance ON public.compromiso FOR UPDATE TO authenticated USING (((responsable_id = auth.uid()) AND (NOT check_analista))) WITH CHECK ((responsable_id = auth.uid()));


--
-- Name: compromiso compromiso_update_revision; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY compromiso_update_revision ON public.compromiso FOR UPDATE TO authenticated USING ((public.app_puede_cerrar_en(empresa_id, asignado_por_id) OR (EXISTS ( SELECT 1
   FROM public.perfil p
  WHERE ((p.id = auth.uid()) AND p.activo AND (p.columna_vb IS NOT NULL) AND (((p.columna_vb = 'B'::text) AND (compromiso.empresa_id = 'BLE'::text)) OR ((p.columna_vb = 'F'::text) AND (compromiso.empresa_id = 'FER'::text)) OR (p.columna_vb = 'A'::text))))) OR (public.app_edita_puntaje() AND ((public.app_puntaje_empresa() = 'TODAS'::text) OR (public.app_puntaje_empresa() = empresa_id))))) WITH CHECK ((public.app_puede_cerrar_en(empresa_id) OR (EXISTS ( SELECT 1
   FROM public.perfil p
  WHERE ((p.id = auth.uid()) AND p.activo AND (p.columna_vb IS NOT NULL) AND (((p.columna_vb = 'B'::text) AND (compromiso.empresa_id = 'BLE'::text)) OR ((p.columna_vb = 'F'::text) AND (compromiso.empresa_id = 'FER'::text)) OR (p.columna_vb = 'A'::text))))) OR (public.app_edita_puntaje() AND ((public.app_puntaje_empresa() = 'TODAS'::text) OR (public.app_puntaje_empresa() = empresa_id)))));


